/* Bài tập đặt câu trực tiếp cho từng chủ điểm ngữ pháp (2 câu/chủ điểm, +20đ/câu). */
window.grammarPracticeData = {"hsk3:10:0":[{"promptVi":"Đặt câu hoàn chỉnh: Hãy đặt cuốn từ điển lên bàn (hoàn thành câu chữ 把 bằng bổ ngữ nơi chốn).","required":[["放在","放到","搁在"]],"minLength":8,"chips":["请你把词典放在桌子上"],"model":"请你把词典放在桌子上。","modelPinyin":"fàng zài zhuōzi shang","hint":"Chủ ngữ + 把 + tân ngữ (xác định) + động từ + thành phần khác"},{"promptVi":"Đặt câu hoàn chỉnh: Điện thoại của tôi đâu? — Tôi để nó trên bàn rồi, bạn ra bàn tìm xem (dùng câu chữ 把).","required":[["放在","放到","搁在"]],"minLength":8,"chips":["我的手机呢","我把它放在桌子上了","你去桌子上找找"],"model":"A：我的手机呢？\nB：我把它放在桌子上了，你去桌子上找找。","modelPinyin":"fàng zài zhuōzi shang le","hint":"Chủ ngữ + 把 + tân ngữ (xác định) + động từ + thành phần khác"}],"hsk3:10:1":[{"promptVi":"Đặt câu hoàn chỉnh: Dưới ảnh hưởng của anh trai, tôi và em trai đều mê bóng đá (phần khuyết kết thúc bằng 下).","required":[["下"]],"minLength":8,"chips":["在哥哥的影响下","我和弟弟都对足球感兴趣了"],"model":"在哥哥的影响下，我和弟弟都对足球感兴趣了。","modelPinyin":"gēge de yǐngxiǎng xià","hint":"在 không chỉ chỉ nơi chốn cụ thể, mà còn chỉ \"phạm vi trừu tượng\": 在学习上 (trong học tập), 在生活中 (trong cuộc sống), 在这一点上 (ở điểm này)."},{"promptVi":"Đặt câu hoàn chỉnh: Trong học tập gặp vấn đề, bạn có thể đến hỏi tôi bất cứ lúc nào (điền lĩnh vực vào khung 在……上).","required":[["学习","工作","生活","汉语","数学","外语"]],"minLength":8,"chips":["在学习上遇到问题","你可以随时来问我"],"model":"在学习上遇到问题，你可以随时来问我。","modelPinyin":"xuéxí","hint":"在 không chỉ chỉ nơi chốn cụ thể, mà còn chỉ \"phạm vi trừu tượng\": 在学习上 (trong học tập), 在生活中 (trong cuộc sống), 在这一点上 (ở điểm này)."}],"hsk3:10:2":[{"promptVi":"Đặt câu hoàn chỉnh: Bạn nộp bài tập cho thầy chưa? — Chưa, tôi chưa mang bài tập đến trường (dùng câu chữ 把 ở dạng phủ định).","required":["没把"],"minLength":8,"chips":["你把作业交给老师了吗","还没有","我没把作业带到学校来"],"model":"A：你把作业交给老师了吗？\nB：还没有，我没把作业带到学校来。","modelPinyin":"méi bǎ zuòyè dài dào xuéxiào lái","hint":"Phủ định (不/没/别) và động từ năng nguyện (想/要/可以) đứng TRƯỚC 把, không chen vào giữa."},{"promptVi":"Đặt câu hoàn chỉnh: Hãy trả cuốn tạp chí này về thư viện giúp tôi, tôi đọc xong rồi (dùng 把…还给…).","required":["还给"],"minLength":8,"chips":["请你把这本杂志还给图书馆","我已经看完了"],"model":"请你把这本杂志还给图书馆，我已经看完了。","modelPinyin":"huán gěi túshūguǎn","hint":"Phủ định (不/没/别) và động từ năng nguyện (想/要/可以) đứng TRƯỚC 把, không chen vào giữa."}],"hsk3:11:0":[{"promptVi":"Đặt câu hoàn chỉnh: Chúng ta đi tàu điện ngầm nhé, hay là bắt taxi? (đưa ra lựa chọn thứ hai bằng 还是).","required":["还是"],"minLength":8,"chips":["我们坐地铁去","还是打车去","坐地铁吧","这个时间打车太堵了"],"model":"A：我们坐地铁去，还是打车去？\nB：坐地铁吧，这个时间打车太堵了。","modelPinyin":"háishì dǎchē qù","hint":"Cả hai đều là \"hoặc\", nhưng 还是 dùng trong CÂU HỎI lựa chọn (A还是B?), 或者 dùng trong CÂU KỂ (nói về lựa chọn chung chung)."},{"promptVi":"Đặt câu hoàn chỉnh: Cuối tuần bạn đi leo núi hoặc ở nhà đọc sách đều được, tôi không đi (điền 或者 vào chỗ trống).","required":["或者"],"minLength":8,"chips":["周末你去爬山或者在家看书都行","我不去了"],"model":"周末你去爬山或者在家看书都行，我不去了。","modelPinyin":"huòzhě","hint":"Cả hai đều là \"hoặc\", nhưng 还是 dùng trong CÂU HỎI lựa chọn (A还是B?), 或者 dùng trong CÂU KỂ (nói về lựa chọn chung chung)."}],"hsk3:11:1":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy mãi không nghe điện thoại — hãy rút ra kết luận bằng 看来.","required":["看来"],"minLength":8,"chips":["他一直没接电话","看来他现在很忙"],"model":"他一直没接电话，看来他现在很忙。","modelPinyin":"kànlái tā xiànzài hěn máng","hint":"看来 + phán đoán"},{"promptVi":"Đặt câu hoàn chỉnh: Ngoài cửa sổ sấm rất to — xem ra sắp có một trận mưa lớn (dùng 看来).","required":["看来"],"minLength":8,"chips":["窗外雷声很大","看来一场大雨要来了"],"model":"窗外雷声很大，看来一场大雨要来了。","modelPinyin":"kànlái yì chǎng dàyǔ yào lái le","hint":"看来 + phán đoán"}],"hsk3:11:2":[{"promptVi":"Đặt câu hoàn chỉnh: Những việc này hôm nay làm xong được không? — Được, chúng ta cùng làm xong hết (dùng câu chữ 把 với bổ ngữ kết quả).","required":["把",["做完","完成"]],"minLength":8,"chips":["这些工作今天能做完吗","能","我们一起把它们都做完"],"model":"A：这些工作今天能做完吗？\nB：能，我们一起把它们都做完。","modelPinyin":"bǎ tāmen dōu zuòwán","hint":"Ôn lại 把 với các bổ ngữ phức tạp hơn: 把 + O + V + 给/到/在 + người/nơi. Nhớ: phủ định và năng nguyện đứng TRƯỚC 把."},{"promptVi":"Đặt câu hoàn chỉnh: Mẹ giặt sạch quần áo rồi xếp từng chiếc vào tủ (hoàn thành phần sau 把 bằng động từ + bổ ngữ kết quả).","required":[["洗干净","洗好","洗完"]],"minLength":8,"chips":["妈妈把衣服洗干净了","一件一件放进了衣柜"],"model":"妈妈把衣服洗干净了，一件一件放进了衣柜。","modelPinyin":"xǐ gānjìng le","hint":"Ôn lại 把 với các bổ ngữ phức tạp hơn: 把 + O + V + 给/到/在 + người/nơi. Nhớ: phủ định và năng nguyện đứng TRƯỚC 把."}],"hsk3:11:3":[{"promptVi":"Đặt câu hoàn chỉnh: Đối với anh ấy, được sống cùng gia đình là quan trọng nhất (phần khuyết dùng mẫu 对……来说).","required":["对","来说"],"minLength":8,"chips":["对他来说","能和家人生活在一起最重要"],"model":"对他来说，能和家人生活在一起最重要。","modelPinyin":"duì tā lái shuō","hint":"对 + người + 来说, + nhận xét"},{"promptVi":"Đặt câu nói: \"Đối với tôi mà nói, học tiếng Trung rất thú vị.\"","required":[["对"],["来说"]],"minLength":5,"chips":["对我来说","学习汉语","很有意思","非常","重要"],"model":"对我来说，学习汉语很有意思。","modelPinyin":"Duì wǒ láishuō, xuéxí Hànyǔ hěn yǒu yìsi.","hint":"Dùng cấu trúc: 对 + [đối tượng] + 来说，..."}],"hsk3:12:0":[{"promptVi":"Đặt câu hoàn chỉnh: Cuối tuần tôi hoặc đi leo núi, hoặc… — hoàn thành vế 或者 thứ hai.","required":["或者"],"minLength":8,"chips":["周末我或者去爬山","或者去公园骑车","反正不在家待着"],"model":"周末我或者去爬山，或者去公园骑车，反正不在家待着。","modelPinyin":"huòzhě qù gōngyuán qí chē","hint":"或者 + A, + 或者 + B"},{"promptVi":"Đặt câu hoàn chỉnh: Nghỉ lễ bạn có dự định gì? — Trả lời bằng mẫu 或者……，或者…….","required":["或者","或者"],"minLength":8,"chips":["放假你有什么打算","或者去南方旅游","或者在家陪父母"],"model":"A：放假你有什么打算？\nB：或者去南方旅游，或者在家陪父母。","modelPinyin":"huòzhě qù nánfāng lǚyóu, huòzhě zài jiā péi fùmǔ","hint":"或者 + A, + 或者 + B"}],"hsk3:12:1":[{"promptVi":"Đặt câu hoàn chỉnh: Vừa nãy còn ngoan, đứa trẻ bỗng òa khóc (dùng 起来 chỉ sự bắt đầu).","required":["起来"],"minLength":8,"chips":["刚才还好好的","孩子突然哭起来了"],"model":"刚才还好好的，孩子突然哭起来了。","modelPinyin":"kū qǐlai le","hint":"Động từ + 起来 / Tính từ + 起来"},{"promptVi":"Đặt câu hoàn chỉnh: Nghe xong câu chuyện cười này, mọi người đều phá lên cười (dùng 起来).","required":["起来"],"minLength":8,"chips":["听了这个笑话","大家都笑起来了"],"model":"听了这个笑话，大家都笑起来了。","modelPinyin":"xiào qǐlai le","hint":"Động từ + 起来 / Tính từ + 起来"}],"hsk3:12:2":[{"promptVi":"Đặt câu hoàn chỉnh: Lần này đi họp ở miền Nam không nhiều người, chỉ có bốn người (bắt đầu bằng 就).","required":["就"],"minLength":8,"chips":["这次去南方开会的人不多","就四个人"],"model":"这次去南方开会的人不多，就四个人。","modelPinyin":"jiù sì ge rén","hint":"就 ngoài nghĩa \"thì\", còn có nghĩa \"CHỈ\" — giới hạn phạm vi, tương đương \"只\". Đọc nhẹ, nhấn vào sự ít ỏi."},{"promptVi":"Đặt câu hoàn chỉnh: Trong lớp rất yên tĩnh, chỉ có mình anh ấy đang chăm chú đọc sách (dùng 就 chỉ phạm vi).","required":["就"],"minLength":8,"chips":["教室里很安静","就他一个人在认真看书"],"model":"教室里很安静，就他一个人在认真看书。","modelPinyin":"jiù tā yí ge rén","hint":"就 ngoài nghĩa \"thì\", còn có nghĩa \"CHỈ\" — giới hạn phạm vi, tương đương \"只\". Đọc nhẹ, nhấn vào sự ít ỏi."}],"hsk3:12:3":[{"promptVi":"Đặt câu hoàn chỉnh: Lời thầy nói rất quan trọng, mọi người hãy ghi lại những điểm chính (dùng 下来).","required":["下来"],"minLength":8,"chips":["老师说的话很重要","请大家把重点记下来"],"model":"老师说的话很重要，请大家把重点记下来。","modelPinyin":"jì xiàlai","hint":"Động từ + 下来"},{"promptVi":"Đặt câu nói: \"Thói quen tốt cần phải kiên trì lâu dài (下来).\"","required":[["下来"]],"minLength":5,"chips":["好习惯","一定要","坚持","下来","每天"],"model":"好习惯一定要坚持下来。","modelPinyin":"Hǎo xíguàn yídìng yào jiānchí xiàlái.","hint":"Động từ + 下来 (duy trì/tiếp tục đến sau này)"}],"hsk3:13:0":[{"promptVi":"Đặt câu hoàn chỉnh: Mai bạn không bận thì… — hoàn thành lời mời; B đã đồng ý và khen món Bắc Kinh của A.","required":[["来","去","一起"]],"minLength":8,"chips":["明天你没事的话","就来我家吃饭吧","好啊","早就听说你做的北京菜特别好吃"],"model":"A：明天你没事的话，就来我家吃饭吧。\nB：好啊，早就听说你做的北京菜特别好吃。","modelPinyin":"jiù lái wǒ jiā chīfàn ba","hint":"Điều kiện + 的话, (就) + kết quả"},{"promptVi":"Đặt câu hoàn chỉnh: Nếu thời tiết đẹp thì… (hoàn thành vế kết quả, thường có 就).","required":["就"],"minLength":8,"chips":["天气好的话","我们就去公园放风筝"],"model":"天气好的话，我们就去公园放风筝。","modelPinyin":"wǒmen jiù qù gōngyuán fàng fēngzheng","hint":"Điều kiện + 的话, (就) + kết quả"}],"hsk3:13:1":[{"promptVi":"Đặt câu hoàn chỉnh: Mẹ dọn căn phòng… (hoàn thành câu chữ 把 bằng bổ ngữ trạng thái).","required":[["得","干净"]],"minLength":8,"chips":["妈妈把房间收拾得干干净净"],"model":"妈妈把房间收拾得干干净净。","modelPinyin":"shōushi de gāngān jìngjìng","hint":"Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ (得……/进去/出来…)"},{"promptVi":"Đặt câu hoàn chỉnh: Ngoài trời gió to quá, bạn ra đóng cửa sổ lại cho chắc (hoàn thành câu chữ 把).","required":["关"],"minLength":8,"chips":["外面风太大了","你去把窗户关紧一点儿"],"model":"外面风太大了，你去把窗户关紧一点儿。","modelPinyin":"guān jǐn yídiǎnr","hint":"Chủ ngữ + 把 + tân ngữ + động từ + bổ ngữ (得……/进去/出来…)"}],"hsk3:13:2":[{"promptVi":"Đặt câu hoàn chỉnh: Hôm qua bạn với Gia Nguyệt đi đâu? — Đi nhà hàng, chúng tôi vừa… vừa…, vui lắm (dùng 一边……一边……).","required":[["一边","边"]],"minLength":8,"chips":["昨天你跟家月去哪儿了","去饭馆了","我们一边吃火锅一边聊天儿","开心极了"],"model":"A：昨天你跟家月去哪儿了？\nB：去饭馆了，我们一边吃火锅一边聊天儿，开心极了。","modelPinyin":"yìbiān chī huǒguō yìbiān liáotiānr","hint":"一边 + việc 1，一边 + việc 2 (cùng chủ ngữ)"},{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy thích vừa chạy bộ vừa nghe nhạc (dùng 一边……一边…… hoặc 边……边……).","required":[["一边","边"]],"minLength":8,"chips":["他喜欢一边跑步一边听音乐","觉得这样跑得更开心"],"model":"他喜欢一边跑步一边听音乐，觉得这样跑得更开心。","modelPinyin":"yìbiān pǎobù yìbiān tīng yīnyuè","hint":"一边 + việc 1，一边 + việc 2 (cùng chủ ngữ)"}],"hsk3:14:0":[{"promptVi":"Đặt câu hoàn chỉnh: Xe đạp của bạn đâu? — Bị bạn học mượn mất rồi (dùng câu bị động 被).","required":["被"],"minLength":8,"chips":["你的自行车呢","被同学借走了"],"model":"A：你的自行车呢？\nB：被同学借走了。","modelPinyin":"bèi tóngxué jiè zǒu le","hint":"Chủ ngữ (chịu tác động) + 被 + (người gây ra) + động từ + thành phần khác"},{"promptVi":"Đặt câu hoàn chỉnh: Chiếc bánh tôi mới mua để trên bàn, quay lại nhìn thì… đã bị em trai ăn hết (dùng 被).","required":["被"],"minLength":8,"chips":["我刚买的蛋糕放在桌子上","回来一看","被弟弟吃完了"],"model":"我刚买的蛋糕放在桌子上，回来一看，被弟弟吃完了。","modelPinyin":"bèi dìdi chī wán le","hint":"Chủ ngữ (chịu tác động) + 被 + (người gây ra) + động từ + thành phần khác"}],"hsk3:14:1":[{"promptVi":"Đặt câu hoàn chỉnh: Tan học bạn định làm gì? — Trả lời bằng mẫu 先……，然后…….","required":["先",["然后","再"]],"minLength":8,"chips":["下课以后","你打算做什么","先去图书馆还书","然后跟朋友去打球"],"model":"A：下课以后，你打算做什么？\nB：先去图书馆还书，然后跟朋友去打球。","modelPinyin":"xiān qù túshūguǎn huán shū, ránhòu gēn péngyou qù dǎ qiú","hint":"先 + việc 1，再/然后 + việc 2"},{"promptVi":"Đặt câu hoàn chỉnh: Mọi người dọn sạch lớp trước, rồi cùng nhau về nhà (vế sau dùng 然后/再).","required":[["然后","再"]],"minLength":8,"chips":["大家先把教室打扫干净","然后再一起回家"],"model":"大家先把教室打扫干净，然后再一起回家。","modelPinyin":"ránhòu zài yìqǐ huí jiā","hint":"先 + việc 1，再/然后 + việc 2"}],"hsk3:14:2":[{"promptVi":"Đặt câu hoàn chỉnh: Mai biểu diễn rồi, tôi hồi hộp quá. — Trấn an bạn bằng mẫu ×什么啊.","required":["什么"],"minLength":8,"chips":["明天就要表演了","我好紧张","紧张什么啊","我们都相信你"],"model":"A：明天就要表演了，我好紧张。\nB：紧张什么啊，我们都相信你。","modelPinyin":"jǐnzhāng shénme a","hint":"Tính từ/động từ + 什么(啊)"},{"promptVi":"Đặt câu hoàn chỉnh: Quán này hơi đắt, đổi quán khác đi. — Đắt gì chứ, hôm nay sinh nhật bạn… (dùng mẫu ×什么啊).","required":["什么"],"minLength":8,"chips":["这家饭馆的菜挺贵的","咱们换一家吧","贵什么啊","今天你生日","想吃什么就吃什么"],"model":"A：这家饭馆的菜挺贵的，咱们换一家吧。\nB：贵什么啊，今天你生日，想吃什么就吃什么。","modelPinyin":"guì shénme a","hint":"Tính từ/động từ + 什么(啊)"}],"hsk3:15:0":[{"promptVi":"Đặt câu hoàn chỉnh: Thầy sẽ căn cứ vào tình hình của từng học sinh mà giao bài tập khác nhau (bắt đầu bằng 根据).","required":["根据"],"minLength":8,"chips":["老师会根据每个学生的情况","给每个学生不同的作业"],"model":"老师会根据每个学生的情况，给每个学生不同的作业。","modelPinyin":"gēnjù měi ge xuésheng de qíngkuàng","hint":"根据 + căn cứ, + hành động/phán đoán"},{"promptVi":"Đặt câu hoàn chỉnh: Căn cứ theo dự báo thời tiết, chúng tôi quyết định đổi giờ xuất phát sang buổi sáng (phần khuyết bắt đầu bằng 根据).","required":["根据"],"minLength":8,"chips":["根据天气预报","我们决定把出发的时间改到早上"],"model":"根据天气预报，我们决定把出发的时间改到早上。","modelPinyin":"gēnjù tiānqì yùbào","hint":"根据 + căn cứ, + hành động/phán đoán"}],"hsk3:15:1":[{"promptVi":"Đặt câu với cụm số lượng lặp lại \"mỗi cái một cái / từng chiếc một\": \"Học sinh từng người từng người bước vào phòng học.\"","required":[["一个一个","一个个"]],"minLength":5,"chips":["学生们","一个一个","走进","教室","里"],"model":"学生们一个一个走进教室里。","modelPinyin":"Xuéshēngmen yí gè yí gè zǒu jìn jiàoshì lǐ.","hint":"Dùng dạng: 一个一个 + động từ"},{"promptVi":"Đặt câu nói: \"Đừng vội, chúng ta từng bước một (一步一步) giải quyết vấn đề.\"","required":[["一步一步"]],"minLength":5,"chips":["别着急","我们","一步一步","解决","问题"],"model":"别着急，我们一步一步解决问题。","modelPinyin":"Bié zháojí, wǒmen yí bù yí bù jiějué wèntí.","hint":"Dùng dạng: 一步一步 + động từ"}],"hsk3:15:2":[{"promptVi":"Đặt câu hoàn chỉnh: Theo bác sĩ, vận động mỗi ngày rất tốt cho sức khỏe (phần khuyết dùng mẫu 在……看来).","required":["在","看来"],"minLength":8,"chips":["在医生看来","每天运动对身体很好"],"model":"在医生看来，每天运动对身体很好。","modelPinyin":"zài yīshēng kànlái","hint":"在 + người/nhóm người + 看来, + nhận định"},{"promptVi":"Đặt câu hoàn chỉnh: Theo người dân trong làng, con sông nhỏ này quan trọng hơn tất cả, vì nó đã nuôi sống mấy thế hệ trong làng.","required":["在","看来"],"minLength":8,"chips":["在村里人看来","这条小河比什么都重要","因为它养了村里几代人"],"model":"在村里人看来，这条小河比什么都重要，因为它养了村里几代人。","modelPinyin":"zài cūnlǐ rén kànlái","hint":"在 + người/nhóm người + 看来, + nhận định"}],"hsk3:15:3":[{"promptVi":"Đặt câu hoàn chỉnh: Chúng tôi đợi ở bến xe, chẳng mấy chốc xe đã đến (dùng 不一会儿).","required":["不一会儿"],"minLength":8,"chips":["我们在车站等着","不一会儿车就来了"],"model":"我们在车站等着，不一会儿车就来了。","modelPinyin":"bù yíhuìr chē jiù lái le","hint":"不一会儿 (+ 就) + sự việc"},{"promptVi":"Đặt câu nói: \"Chẳng mấy chốc (不一会儿), trời đã bắt đầu mưa rồi.\"","required":[["不一会儿"]],"minLength":5,"chips":["不一会儿","外面","就","开始","下雨了"],"model":"不一会儿，外面就开始下雨了。","modelPinyin":"Bù yíhuìr, wàimiàn jiù kāishǐ xià yǔ le.","hint":"不一会儿 + (chủ ngữ) + 就 + động từ"}],"hsk3:16:0":[{"promptVi":"Đặt câu hoàn chỉnh: Ở hội thao, cậu ấy lúc thì thi chạy, lúc thì… (vế sau cũng bắt đầu bằng 一会儿).","required":["一会儿"],"minLength":8,"chips":["运动会上","他一会儿参加跑步比赛","一会儿参加跳远比赛"],"model":"运动会上，他一会儿参加跑步比赛，一会儿参加跳远比赛。","modelPinyin":"yíhuìr cānjiā tiàoyuǎn bǐsài","hint":"一会儿 + hành động/trạng thái 1，一会儿 + hành động/trạng thái 2"},{"promptVi":"Đặt câu hoàn chỉnh: Chú mèo này rất đáng yêu, lúc nằm ngủ trên sofa, lúc thì… (vế sau bắt đầu bằng 一会儿).","required":["一会儿"],"minLength":8,"chips":["这只小猫很可爱","一会儿躺在沙发上睡觉","一会儿跑到花园里玩儿"],"model":"这只小猫很可爱，一会儿躺在沙发上睡觉，一会儿跑到花园里玩儿。","modelPinyin":"yíhuìr pǎo dào huāyuán lǐ wánr","hint":"一会儿 + hành động/trạng thái 1，一会儿 + hành động/trạng thái 2"}],"hsk3:16:1":[{"promptVi":"Đặt câu hoàn chỉnh: Về kế hoạch đi vườn thú lần này, tôi còn vài câu muốn hỏi bạn (phần khuyết bắt đầu bằng 关于).","required":["关于"],"minLength":8,"chips":["关于这次去动物园的安排","我还有一些问题想问你"],"model":"关于这次去动物园的安排，我还有一些问题想问你。","modelPinyin":"guānyú zhè cì qù dòngwùyuán de ānpái","hint":"关于 + danh từ / cụm danh từ (+ 的 + danh từ)"},{"promptVi":"Đặt câu hoàn chỉnh: Gần đây bạn đang đọc sách gì? — Một cuốn sách về động vật hoang dã (dùng 关于).","required":["关于"],"minLength":8,"chips":["你最近在看什么书","一本关于野生动物的书"],"model":"A：你最近在看什么书？\nB：一本关于野生动物的书。","modelPinyin":"yì běn guānyú yěshēng dòngwù de shū","hint":"关于 + danh từ / cụm danh từ (+ 的 + danh từ)"}],"hsk3:16:2":[{"promptVi":"Đặt câu hoàn chỉnh: Bạn thấy tập thể dục buổi sáng hay buổi tối tốt hơn? — Nói chung… (bắt đầu bằng 一般来说).","required":["一般来说"],"minLength":8,"chips":["你觉得早上锻炼好还是晚上锻炼好","一般来说","早上锻炼更好"],"model":"A：你觉得早上锻炼好还是晚上锻炼好？\nB：一般来说，早上锻炼更好。","modelPinyin":"yìbān lái shuō, zǎoshang duànliàn gèng hǎo","hint":"一般来说，+ nhận định chung"},{"promptVi":"Đặt câu hoàn chỉnh: Nói chung, học ngoại ngữ cần nghe nói nhiều, không thể chỉ đọc sách (điền 一般来说 ở đầu câu).","required":["一般来说"],"minLength":8,"chips":["一般来说","学习外语需要多听多说","不能只看书"],"model":"一般来说，学习外语需要多听多说，不能只看书。","modelPinyin":"yìbān lái shuō","hint":"一般来说，+ nhận định chung"}],"hsk3:16:3":[{"promptVi":"Đặt câu hoàn chỉnh: Sao hôm nay bạn đến sớm thế? — Tôi ra khỏi nhà sớm hơn thường ngày 20 phút (dùng mẫu 比…早…+ số lượng).","required":["比",["早","多","晚","少"]],"minLength":8,"chips":["你今天怎么来得这么早","我比平时早出门了二十分钟"],"model":"A：你今天怎么来得这么早？\nB：我比平时早出门了二十分钟。","modelPinyin":"wǒ bǐ píngshí zǎo chūmén le èrshí fēnzhōng","hint":"A + 比 + B + 多/少/早/晚 + động từ + cụm số lượng"},{"promptVi":"Đặt câu so sánh có số lượng: \"Hôm nay tôi đến sớm hơn bạn 10 phút.\"","required":[["比"],["早"],["分钟"]],"minLength":5,"chips":["今天","我","比你","早来","十分钟"],"model":"今天我比你早来十分钟。","modelPinyin":"Jīntiān wǒ bǐ nǐ zǎo lái shí fēnzhōng.","hint":"A + 比 + B + 早/晚/多/少 + động từ + số lượng"}],"hsk3:17:0":[{"promptVi":"Đặt câu hoàn chỉnh: Đứa trẻ vừa thấy mẹ liền chạy về phía mẹ (dùng 向).","required":["向"],"minLength":8,"chips":["孩子一看见妈妈","就向她跑过去了"],"model":"孩子一看见妈妈，就向她跑过去了。","modelPinyin":"xiàng tā pǎo guòqu le","hint":"向 + đại từ / danh từ / cụm danh từ + động từ"},{"promptVi":"Đặt câu hoàn chỉnh: Nếu có chỗ không hiểu, bạn có thể hỏi thêm thầy cô (dùng 向…请教/学习).","required":["向"],"minLength":8,"chips":["如果有不懂的地方","你可以多向老师请教"],"model":"如果有不懂的地方，你可以多向老师请教。","modelPinyin":"xiàng lǎoshī qǐngjiào","hint":"向 + đại từ / danh từ / cụm danh từ + động từ"}],"hsk3:17:1":[{"promptVi":"Đặt câu hoàn chỉnh: Năm nay nghỉ tôi vẫn muốn đi Nam Kinh. — Chẳng phải năm ngoái bạn vừa đi rồi sao? (dùng 不是……吗？).","required":["不是","吗"],"minLength":8,"chips":["今年放假我还想去南京","你不是去年刚去过吗"],"model":"A：今年放假我还想去南京。\nB：你不是去年刚去过吗？","modelPinyin":"nǐ bú shì qùnián gāng qùguo ma","hint":"不是 + nội dung cần xác nhận / nhấn mạnh + 吗？"},{"promptVi":"Đặt câu phản vấn: \"Chẳng phải hôm nay là sinh nhật của bạn sao?\"","required":[["不是"],["吗"]],"minLength":5,"chips":["今天","不是","你的","生日","吗"],"model":"今天不是你的生日吗？","modelPinyin":"Jīntiān bú shì nǐ de shēngrì ma?","hint":"不是 + ... + 吗？"}],"hsk3:17:2":[{"promptVi":"Đặt câu hoàn chỉnh: Muốn nâng cao tiếng Trung phải nghe và xem nhiều, càng phải nói và luyện nhiều (vế sau bắt đầu bằng 更).","required":["更"],"minLength":8,"chips":["想提高中文水平要多听多看","更要多说多练"],"model":"想提高中文水平要多听多看，更要多说多练。","modelPinyin":"gèng yào duō shuō duō liàn","hint":"Mệnh đề 1，更 + mệnh đề / nội dung có mức độ cao hơn"},{"promptVi":"Đặt câu hoàn chỉnh: Sau khi biết đi xe đạp, anh ấy học bơi, hơn nữa còn mê cả chạy bộ (vế sau dùng 更).","required":["更"],"minLength":8,"chips":["学会骑车以后","他学会了游泳","更爱上了跑步"],"model":"学会骑车以后，他学会了游泳，更爱上了跑步。","modelPinyin":"gèng àishang le pǎobù","hint":"Mệnh đề 1，更 + mệnh đề / nội dung có mức độ cao hơn"}],"hsk3:17:3":[{"promptVi":"Đặt câu hoàn chỉnh: Bạn ngày nào cũng ra sân tập à? — Ừ, chỉ luyện mỗi ngày mới chơi tốt hơn được (dùng 只有……，才……).","required":["只有","才"],"minLength":8,"chips":["你每天都去球场练习吗","对","只有每天练习","才能打得更好"],"model":"A：你每天都去球场练习吗？\nB：对，只有每天练习，才能打得更好。","modelPinyin":"zhǐyǒu měitiān liànxí, cái néng dǎ de gèng hǎo","hint":"只有 + điều kiện，才 + kết quả"},{"promptVi":"Đặt câu hoàn chỉnh: Chỉ khi nghe nhiều, nói nhiều, xem nhiều thì trình độ tiếng Trung của bạn mới thật sự tiến bộ (phần khuyết bắt đầu bằng 只有).","required":["只有"],"minLength":8,"chips":["只有多听","多说","多看","你的中文水平才能真正提高"],"model":"只有多听、多说、多看，你的中文水平才能真正提高。","modelPinyin":"zhǐyǒu duō tīng, duō shuō, duō kàn","hint":"只有 + điều kiện，才 + kết quả"}],"hsk3:18:0":[{"promptVi":"Đặt câu dùng số ước lượng: \"Tôi đã học tiếng Trung khoảng một hai năm rồi.\"","required":[["一两","两三"]],"minLength":5,"chips":["我","学汉语","学了","一两年","了"],"model":"我学汉语学了一两年了。","modelPinyin":"Wǒ xué Hànyǔ xué le yì liǎng nián le.","hint":"Hai số liền kề (一两 / 两三) + lượng từ/danh từ"},{"promptVi":"Đặt câu dùng số ước lượng: \"Từ đây đến nhà ga mất khoảng bảy tám phút.\"","required":[["七八","五六","三四"]],"minLength":5,"chips":["从这儿","到火车站","大概要","七八分钟","左右"],"model":"从这儿到火车站大概要七八分钟。","modelPinyin":"Cóng zhèr dào huǒchēzhàn dàgài yào qī bā fēnzhōng.","hint":"Hai số liền kề (五六 / 七八) + 分钟"}],"hsk3:18:1":[{"promptVi":"Đặt câu hoàn chỉnh: Cuộc gọi lúc nãy là mẹ tôi gọi, bà hỏi khi nào tôi về nhà (điền 刚才 ở đầu câu).","required":["刚才"],"minLength":8,"chips":["刚才的电话是我妈妈打来的","她问我什么时候回家"],"model":"刚才的电话是我妈妈打来的，她问我什么时候回家。","modelPinyin":"gāngcái","hint":"刚才 (danh từ chỉ thời gian) · 刚刚 (phó từ, đứng sau chủ ngữ)"},{"promptVi":"Đặt câu hoàn chỉnh: Bạn học bơi từ khi nào? — Vừa mới học cùng bạn học (dùng 刚刚).","required":["刚刚"],"minLength":8,"chips":["你是什么时候学会游泳的","刚刚跟同学学的"],"model":"A：你是什么时候学会游泳的？\nB：刚刚跟同学学的。","modelPinyin":"gānggāng gēn tóngxué xué de","hint":"刚才 (danh từ chỉ thời gian) · 刚刚 (phó từ, đứng sau chủ ngữ)"}],"hsk3:18:2":[{"promptVi":"Đặt câu hoàn chỉnh: Bạn tốt với mọi người quá nhỉ? — Tôi tin chỉ cần mình tốt với người khác thì người khác cũng sẽ tốt với mình (hoàn thành vế kết quả).","required":[["会","就","也"]],"minLength":8,"chips":["你对大家都这么好啊","我相信只要我对别人好","别人也会对我好"],"model":"A：你对大家都这么好啊？\nB：我相信只要我对别人好，别人也会对我好。","modelPinyin":"biérén yě huì duì wǒ hǎo","hint":"只要 + điều kiện đủ，就 + kết quả"},{"promptVi":"Đặt câu hoàn chỉnh: Chỉ cần bạn kiên trì ngủ sớm mỗi ngày thì sức khỏe sẽ tốt lên (vế sau có 就).","required":["就"],"minLength":8,"chips":["只要你坚持每天早睡","身体就一定会好起来"],"model":"只要你坚持每天早睡，身体就一定会好起来。","modelPinyin":"shēntǐ jiù yídìng huì hǎo qǐlai","hint":"只要 + điều kiện đủ，就 + kết quả"}],"hsk3:18:3":[{"promptVi":"Đặt câu hoàn chỉnh: Từ khi chuyển đến Bắc Kinh, anh ấy bắt đầu học nấu món Trung Quốc (vế sau thường có 就).","required":["就"],"minLength":8,"chips":["从搬到北京起","他就开始学做中国菜了"],"model":"从搬到北京起，他就开始学做中国菜了。","modelPinyin":"tā jiù kāishǐ xué zuò Zhōngguó cài le","hint":"从 + mốc thời gian / sự việc + 起"},{"promptVi":"Đặt câu hoàn chỉnh: Từ chuyến du lịch lần đó, tôi bắt đầu thích chụp ảnh (phần khuyết dùng mẫu 从……起).","required":["从","起"],"minLength":8,"chips":["从那次旅游起","我就开始喜欢拍照了"],"model":"从那次旅游起，我就开始喜欢拍照了。","modelPinyin":"cóng nà cì lǚyóu qǐ","hint":"从 + mốc thời gian / sự việc + 起"}],"hsk4-thuong:1:0":[{"promptVi":"Đặt câu hoàn chỉnh: Sau này có bất kỳ vấn đề gì đều có thể đến văn phòng tìm tôi (điền 任何 trước danh từ).","required":["任何"],"minLength":8,"chips":["以后有任何问题","都可以来办公室找我"],"model":"以后有任何问题，都可以来办公室找我。","modelPinyin":"rènhé","hint":"任何 + danh từ + 都/也 …"},{"promptVi":"Đặt câu hoàn chỉnh: Mai 8 giờ xuất phát, bất kỳ ai cũng không được đến muộn (phần khuyết bắt đầu bằng 任何人).","required":["任何"],"minLength":8,"chips":["明天八点出发","任何人都不能迟到"],"model":"明天八点出发，任何人都不能迟到。","modelPinyin":"rènhé rén dōu bùnéng","hint":"任何 + danh từ + 都/也 …"}],"hsk4-thuong:1:1":[{"promptVi":"Đặt câu hoàn chỉnh: Bài thi ngày mai bạn có tự tin không? — Nếu ôn lại một lượt nữa thì tôi sẽ tự tin hơn (dùng 要是……，就……).","required":["要是","就"],"minLength":8,"chips":["明天的考试你有信心吗","要是再复习一遍","我就更有信心了"],"model":"A：明天的考试你有信心吗？\nB：要是再复习一遍，我就更有信心了。","modelPinyin":"yàoshi zài fùxí yí biàn, wǒ jiù gèng yǒu xìnxīn le","hint":"要是 + điều kiện，就 + kết quả"},{"promptVi":"Đặt câu hoàn chỉnh: Nếu bạn có thời gian thì đi nhà sách mua sách cùng tôi nhé (điền 要是).","required":["要是"],"minLength":8,"chips":["你要是有时间","就陪我去书店买书吧"],"model":"你要是有时间，就陪我去书店买书吧。","modelPinyin":"yàoshi","hint":"要是 + điều kiện，就 + kết quả"}],"hsk4-thuong:1:2":[{"promptVi":"Đặt câu hoàn chỉnh: Cùng với thời gian sống ở Trung Quốc ngày càng dài, tiếng Hán của anh ấy nói ngày càng lưu loát (phần khuyết bắt đầu bằng 随着).","required":["随着"],"minLength":8,"chips":["随着在中国生活的时间越来越长","他的汉语说得越来越流利了"],"model":"随着在中国生活的时间越来越长，他的汉语说得越来越流利了。","modelPinyin":"suízhe zài Zhōngguó shēnghuó de shíjiān yuèláiyuè cháng","hint":"随着 + sự thay đổi，+ việc xảy ra theo"},{"promptVi":"Đặt câu hoàn chỉnh: Cùng với sự phát triển của Trung Quốc, sinh viên nước ngoài đến du học ngày càng nhiều.","required":["随着"],"minLength":8,"chips":["随着中国的发展","来中国留学的外国学生一年比一年多"],"model":"随着中国的发展，来中国留学的外国学生一年比一年多。","modelPinyin":"suízhe Zhōngguó de fāzhǎn","hint":"随着 + sự thay đổi，+ việc xảy ra theo"}],"hsk4-thuong:1:3":[{"promptVi":"Đặt câu hoàn chỉnh: Đến Trung Quốc du học, một mặt học tốt tiếng Hán, mặt khác còn kết bạn được nhiều (phần khuyết bắt đầu bằng 一方面).","required":["一方面"],"minLength":8,"chips":["来中国留学","一方面能学好汉语","另一方面也能交到很多朋友"],"model":"来中国留学，一方面能学好汉语，另一方面也能交到很多朋友。","modelPinyin":"yì fāngmiàn néng xuéhǎo Hànyǔ","hint":"一方面 + khía cạnh 1，另一方面 + khía cạnh 2"},{"promptVi":"Đặt câu song song: \"Đọc sách một mặt giúp mở mang kiến thức, mặt khác giúp thư giãn.\"","required":[["一方面"],["另一方面"]],"minLength":5,"chips":["看书","一方面","能增长知识","另一方面","也能放松"],"model":"看书一方面能增长知识，另一方面也能放松心情。","modelPinyin":"Kànshū yì fāngmiàn néng zēngzhǎng zhīshi, lìng yì fāngmiàn yě néng fàngsōng xīnqíng.","hint":"一方面……，另一方面……"}],"hsk4-thuong:2:0":[{"promptVi":"Đặt câu hoàn chỉnh: Tôi sợ lần này thi không tốt. — Đừng lo, cứ ôn tập cho tốt là được (câu trả lời kết thúc bằng 就是了).","required":["就是了"],"minLength":8,"chips":["我怕这次考试考不好","别担心","好好复习就是了"],"model":"A：我怕这次考试考不好。\nB：别担心，好好复习就是了。","modelPinyin":"hǎohāo fùxí jiù shì le","hint":"Cụm động từ + 就是了"},{"promptVi":"Đặt câu hoàn chỉnh: Quyết định thuê nhà rồi chứ? — Rồi, mai tôi gọi điện cho chủ nhà là xong (kết thúc bằng 就是了).","required":["就是了"],"minLength":8,"chips":["房子决定租了吗","决定了","我明天给房东打个电话就是了"],"model":"A：房子决定租了吗？\nB：决定了，我明天给房东打个电话就是了。","modelPinyin":"gěi fángdōng dǎ ge diànhuà jiù shì le","hint":"Cụm động từ + 就是了"}],"hsk4-thuong:2:1":[{"promptVi":"Đặt câu hoàn chỉnh: Căn phòng này lấy sáng rất tốt, nhưng… (bổ sung một ý hạn chế bằng 不过).","required":["不过"],"minLength":8,"chips":["这个房间采光很好","不过离学校有点儿远"],"model":"这个房间采光很好，不过离学校有点儿远。","modelPinyin":"búguò lí xuéxiào yǒudiǎnr yuǎn","hint":"Ý chính，不过 + ý bổ sung/hạn chế"},{"promptVi":"Đặt câu hoàn chỉnh: Công việc mới lương khá cao, nhưng mỗi ngày phải tăng ca đến khuya (vế sau dùng 不过).","required":["不过"],"minLength":8,"chips":["新工作工资挺高的","不过每天要加班到很晚"],"model":"新工作工资挺高的，不过每天要加班到很晚。","modelPinyin":"búguò měitiān yào jiābān dào hěn wǎn","hint":"Ý chính，不过 + ý bổ sung/hạn chế"}],"hsk4-thuong:2:2":[{"promptVi":"Đặt câu hoàn chỉnh: Chủ nhà giới thiệu căn nhà một lượt, và còn bảo chúng tôi cách đóng tiền điện nước (vế sau bắt đầu bằng 并).","required":["并"],"minLength":8,"chips":["房东把房子介绍了一遍","并告诉我们水电费怎么交"],"model":"房东把房子介绍了一遍，并告诉我们水电费怎么交。","modelPinyin":"bìng gàosù wǒmen shuǐdiànfèi zěnme jiāo","hint":"…，并 + động từ 2 âm tiết … · 并 + 不/没 …"},{"promptVi":"Đặt câu hoàn chỉnh: Tin này tôi chỉ nghe nói thôi, hoàn toàn không biết có thật hay không (dùng 并不知道).","required":["并"],"minLength":8,"chips":["这个消息我只是听说","并不知道是不是真的"],"model":"这个消息我只是听说，并不知道是不是真的。","modelPinyin":"bìng bù zhīdào shì bù shì zhēn de","hint":"…，并 + động từ 2 âm tiết … · 并 + 不/没 …"}],"hsk4-thuong:2:3":[{"promptVi":"Đặt câu hoàn chỉnh: Do mấy ngày nay mưa liên tục nên hội thao dời sang tuần sau (phần khuyết bắt đầu bằng 由于).","required":["由于"],"minLength":8,"chips":["由于这几天一直下雨","所以运动会改到下星期了"],"model":"由于这几天一直下雨，所以运动会改到下星期了。","modelPinyin":"yóuyú zhè jǐ tiān yìzhí xià yǔ","hint":"由于 + nguyên nhân，所以/因此 + kết quả"},{"promptVi":"Đặt câu với \"由于\": \"Do thời tiết quá lạnh, chúng tôi quyết định ở nhà.\"","required":[["由于"]],"minLength":5,"chips":["由于","天气太冷","我们","决定","待在家里"],"model":"由于天气太冷，我们决定待在家里。","modelPinyin":"Yóuyú tiānqì tài lěng, wǒmen juédìng dāi zài jiālǐ.","hint":"由于 + [nguyên nhân], [kết quả]"}],"hsk4-thuong:3:0":[{"promptVi":"Đặt câu hoàn chỉnh: Cái áo này đẹp thì đẹp thật, chỉ là đắt quá (vế sau bắt đầu bằng 就是).","required":["就是"],"minLength":8,"chips":["这件衣服好看是好看","就是太贵了"],"model":"这件衣服好看是好看，就是太贵了。","modelPinyin":"jiù shì tài guì le","hint":"X 是 X，就是/不过 + ý hạn chế"},{"promptVi":"Đặt câu hoàn chỉnh: Khu nhà này yên tĩnh thì yên tĩnh thật, nhưng hơi xa ga tàu điện ngầm (vế sau dùng 不过).","required":["不过"],"minLength":8,"chips":["这个小区安静是安静","不过离地铁站有点儿远"],"model":"这个小区安静是安静，不过离地铁站有点儿远。","modelPinyin":"búguò lí dìtiězhàn yǒudiǎnr yuǎn","hint":"X 是 X，就是/不过 + ý hạn chế"}],"hsk4-thuong:3:1":[{"promptVi":"Đặt câu hoàn chỉnh: Giờ bạn dùng điện thoại còn thạo hơn tôi! — Tôi không chỉ biết quét mã thanh toán, còn biết mua vé máy bay trên mạng nữa (dùng 不仅……，还……).","required":["不仅",["还","而且"]],"minLength":8,"chips":["你现在手机用得比我还熟练","我不仅会扫码结账","还会在网上买机票了"],"model":"A：你现在手机用得比我还熟练！\nB：我不仅会扫码结账，还会在网上买机票了。","modelPinyin":"wǒ bùjǐn huì sǎomǎ jiézhàng, hái huì zài wǎngshang mǎi jīpiào le","hint":"Chủ ngữ + 不仅/不光 + ý 1，还/而且 + ý 2"},{"promptVi":"Đặt câu hoàn chỉnh: Quán ăn này không chỉ ngon mà còn thường giảm giá (điền 不仅, vế 还已经 cho sẵn).","required":["不仅"],"minLength":8,"chips":["这家饭馆不仅味道好","还经常打折"],"model":"这家饭馆不仅味道好，还经常打折。","modelPinyin":"bùjǐn","hint":"Chủ ngữ + 不仅/不光 + ý 1，还/而且 + ý 2"}],"hsk4-thuong:3:2":[{"promptVi":"Đặt câu hoàn chỉnh: Cuối tuần trung tâm thương mại đông người vô cùng, thậm chí cửa ra vào cũng chật kín người (dùng 甚至).","required":["甚至"],"minLength":8,"chips":["周末商场里人特别多","甚至连门口都站满了人"],"model":"周末商场里人特别多，甚至连门口都站满了人。","modelPinyin":"shènzhì lián ménkǒu dōu zhàn mǎn le rén","hint":"…，甚至 + tình huống bất ngờ nhất"},{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy học chăm quá, thậm chí quên cả ăn trưa (dùng 甚至).","required":["甚至"],"minLength":8,"chips":["他学习太认真了","甚至忘了吃午饭"],"model":"他学习太认真了，甚至忘了吃午饭。","modelPinyin":"shènzhì wàng le chī wǔfàn","hint":"…，甚至 + tình huống bất ngờ nhất"}],"hsk4-thuong:3:3":[{"promptVi":"Đặt câu hoàn chỉnh: Sao bạn chọn học y? — Từ nhỏ tôi đã muốn làm bác sĩ, thế là lên đại học chọn ngành y (vế sau bắt đầu bằng 于是).","required":["于是"],"minLength":8,"chips":["你为什么选择学医","我从小就想当医生","于是上大学时选择了医学专业"],"model":"A：你为什么选择学医？\nB：我从小就想当医生，于是上大学时选择了医学专业。","modelPinyin":"yúshì shàng dàxué shí xuǎnzé le yīxué zhuānyè","hint":"Việc trước，于是 + việc tiếp theo"},{"promptVi":"Đặt câu với \"于是\": \"Trời đột nhiên đổ mưa, thế là chúng tôi vào quán cà phê.\"","required":[["于是"]],"minLength":5,"chips":["突然下雨了","于是","我们","走进了","一家咖啡店"],"model":"突然下雨了，于是我们走进了一家咖啡店。","modelPinyin":"Tūrán xià yǔ le, yúshì wǒmen zǒu jìn le yì jiā kāfēidiàn.","hint":"[Sự việc], 于是 + [hành động tiếp theo]"}],"hsk4-thuong:4:0":[{"promptVi":"Đặt câu hoàn chỉnh: Mấy thùng này một mình bạn chuyển hết được không? — Nhiều quá, một mình tôi chuyển không nổi (dùng bổ ngữ khả năng 不了).","required":[["不了","不完"]],"minLength":8,"chips":["这些箱子你一个人搬得完吗","太多了","我一个人搬不了"],"model":"A：这些箱子你一个人搬得完吗？\nB：太多了，我一个人搬不了。","modelPinyin":"bān bù liǎo","hint":"Động từ + 得了 (làm nổi) / 不了 (không làm nổi)"},{"promptVi":"Đặt câu hoàn chỉnh: Yên tâm, chút việc này một mình tôi làm nổi (dùng bổ ngữ khả năng 得了).","required":[["得了"]],"minLength":8,"chips":["放心吧","这点儿工作我一个人做得了"],"model":"放心吧，这点儿工作我一个人做得了。","modelPinyin":"zuò dé liǎo","hint":"Động từ + 得了 (làm nổi) / 不了 (không làm nổi)"}],"hsk4-thuong:4:1":[{"promptVi":"Đặt câu hoàn chỉnh: Hôm nay còn đi leo núi không? — Muộn quá rồi, đừng đi nữa, với lại… (thêm một lý do bằng 再说).","required":["再说"],"minLength":8,"chips":["今天还去爬山吗","太晚了","别去了","再说山上风还很大"],"model":"A：今天还去爬山吗？\nB：太晚了，别去了，再说山上风还很大。","modelPinyin":"zàishuō shān shang fēng hái hěn dà","hint":"Lý do 1，再说 + lý do 2"},{"promptVi":"Đặt câu hoàn chỉnh: Cái áo này màu không đẹp, hơn nữa giá cũng đắt, chúng ta xem cái khác đi (lý do thứ hai bắt đầu bằng 再说).","required":["再说"],"minLength":8,"chips":["这件衣服颜色不好看","再说价格也太贵","我们再看看别的吧"],"model":"这件衣服颜色不好看，再说价格也太贵，我们再看看别的吧。","modelPinyin":"zàishuō jiàgé yě tài guì","hint":"Lý do 1，再说 + lý do 2"}],"hsk4-thuong:4:2":[{"promptVi":"Đặt câu hoàn chỉnh: Quán ăn nhỏ này vừa sạch vừa rẻ, chúng tôi hay đến ăn (dùng 既……，又……).","required":["既","又"],"minLength":8,"chips":["这家小饭馆既干净又便宜","我们常去吃"],"model":"这家小饭馆既干净又便宜，我们常去吃。","modelPinyin":"jì gānjìng yòu piányi","hint":"既 + tính chất 1，又/也 + tính chất 2"},{"promptVi":"Đặt câu hoàn chỉnh: Học tiếng Hán rất thú vị, vừa hiểu văn hóa Trung Quốc, cũng kết bạn được với người Trung Quốc (dùng 既……，也……).","required":["既","也"],"minLength":8,"chips":["学汉语很有意思","既能了解中国文化","也能交到中国朋友"],"model":"学汉语很有意思，既能了解中国文化，也能交到中国朋友。","modelPinyin":"jì néng liǎojiě Zhōngguó wénhuà, yě néng jiāodào Zhōngguó péngyou","hint":"既 + tính chất 1，又/也 + tính chất 2"}],"hsk4-thuong:4:3":[{"promptVi":"Đặt câu hoàn chỉnh: Chuyến bay 12 giờ, chúng ta 9 giờ xuất phát, có kịp không? (phần khuyết dùng 来得及).","required":["来得及"],"minLength":8,"chips":["十二点的飞机","我们九点出发","来得及吗","放心","时间完全来得及"],"model":"A：十二点的飞机，我们九点出发，来得及吗？\nB：放心，时间完全来得及。","modelPinyin":"láidejí ma","hint":"来得及 / 来不及 + động từ"},{"promptVi":"Đặt câu với \"来得及/来不及\": \"Bây giờ xuất phát vẫn còn kịp chuyến tàu lúc 8 giờ.\"","required":[["来得及","来不及"]],"minLength":5,"chips":["现在出发","还","来得及","赶上","八点的火车"],"model":"现在出发还来得及赶上八点的火车。","modelPinyin":"Xiànzài chūfā hái láidejí gǎnshàng bā diǎn de huǒchē.","hint":"Dùng 来得及 (kịp) hoặc 来不及 (không kịp)"}],"hsk4-thuong:5:0":[{"promptVi":"Đặt câu hoàn chỉnh: Từ trường đến sân bay, đi tàu điện ngầm ít nhất mất một tiếng (dùng 至少).","required":["至少"],"minLength":8,"chips":["从学校到机场","坐地铁至少要一个小时"],"model":"从学校到机场，坐地铁至少要一个小时。","modelPinyin":"zhìshǎo yào yí ge xiǎoshí","hint":"至少 + số lượng/mức độ"},{"promptVi":"Đặt câu hoàn chỉnh: Bữa này khoảng bao nhiêu tiền? — Ít nhất cũng phải 300 tệ (dùng 至少).","required":["至少"],"minLength":8,"chips":["这顿饭大概要多少钱","至少要三百块"],"model":"A：这顿饭大概要多少钱？\nB：至少要三百块。","modelPinyin":"zhìshǎo yào sānbǎi kuài","hint":"至少 + số lượng/mức độ"}],"hsk4-thuong:5:1":[{"promptVi":"Đặt câu hoàn chỉnh: Số món này bốn người ăn có đủ không? — Đủ rồi, chúng ta còn gọi thêm một món canh nữa.","required":["够"],"minLength":8,"chips":["这些菜四个人吃","够吗","够了","我们还点了一个汤"],"model":"A：这些菜四个人吃，够吗？\nB：够了，我们还点了一个汤。","modelPinyin":"gòu le, wǒmen hái diǎn le yí ge tāng","hint":"够 + động từ/danh từ · 够 + tính từ + 的"},{"promptVi":"Đặt câu hoàn chỉnh: Cái áo len này đủ dày đấy, mùa đông mặc vừa đẹp (dùng mẫu 够 + tính từ + 的).","required":["够"],"minLength":8,"chips":["这件毛衣够厚的","冬天穿正好"],"model":"这件毛衣够厚的，冬天穿正好。","modelPinyin":"gòu hòu de","hint":"够 + động từ/danh từ · 够 + tính từ + 的"}],"hsk4-thuong:5:2":[{"promptVi":"Đặt câu hoàn chỉnh: Bữa hôm nay ai mời? — Không cần mời, mỗi người tự trả phần của mình (dùng mẫu 各×各的).","required":[["各付各","各吃各","各点各"]],"minLength":8,"chips":["今天这顿饭谁请客","不用请","我们各付各的吧"],"model":"A：今天这顿饭谁请客？\nB：不用请，我们各付各的吧。","modelPinyin":"wǒmen gè fù gè de ba","hint":"各 + động từ + 各的 (+ tân ngữ)"},{"promptVi":"Đặt câu hoàn chỉnh: Phòng ký túc bốn người đến từ bốn tỉnh, ai nói tiếng địa phương của người nấy, chẳng ai hiểu ai (dùng mẫu 各×各的).","required":["各","各"],"minLength":8,"chips":["宿舍里四个人","来自四个省","各说各的方言","谁也听不懂谁的"],"model":"宿舍里四个人，来自四个省，各说各的方言，谁也听不懂谁的。","modelPinyin":"gè shuō gè de fāngyán","hint":"各 + động từ + 各的 (+ tân ngữ)"}],"hsk4-thuong:5:3":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy đi siêu thị mua sữa, bánh mì và các loại thực phẩm khác (điền 等 để khép danh sách liệt kê).","required":["等"],"minLength":8,"chips":["他去超市买了牛奶","面包等食品","准备明天带去公司"],"model":"他去超市买了牛奶、面包等食品，准备明天带去公司。","modelPinyin":"děng","hint":"等 + thời gian/điều kiện，… / …，等…再…"},{"promptVi":"Đặt câu với \"等\" (đợi đến khi): \"Đợi khi bạn tan làm, chúng ta cùng đi ăn tối nhé.\"","required":[["等"]],"minLength":5,"chips":["等","你下班了","我们","一起去","吃晚饭吧"],"model":"等你下班了，我们一起去吃晚饭吧。","modelPinyin":"Děng nǐ xiàbān le, wǒmen yìqǐ qù chī wǎnfàn ba.","hint":"等 + [thời điểm/hành động] + , [kết quả]"}],"hsk4-thuong:5:4":[{"promptVi":"Đặt câu liệt kê với \"等\": \"Tôi thích ăn các loại hoa quả như táo, chuối, dưa hấu.\"","required":[["等"]],"minLength":5,"chips":["我喜欢吃","苹果","香蕉","西瓜","等水果"],"model":"我喜欢吃苹果、香蕉、西瓜等水果。","modelPinyin":"Wǒ xǐhuan chī píngguǒ, xiāngjiāo, xīguā děng shuǐguǒ.","hint":"A, B, C + 等 + [danh từ chung]"},{"promptVi":"Đặt câu liệt kê với \"等\": \"Cửa hàng này bán áo sơ mi, quần bò, giày thể thao v.v.\"","required":[["等"]],"minLength":5,"chips":["这家店","卖","衬衫","牛仔裤","等衣服"],"model":"这家店卖衬衫、牛仔裤、运动鞋等商品。","modelPinyin":"Zhè jiā diàn mài chènshān, niúzǎikù, yùndòngxié děng shāngpǐn.","hint":"Liệt kê 2–3 món + 等 (+ danh từ)"}],"hsk4-thuong:6:0":[{"promptVi":"Đặt câu hoàn chỉnh: Mấy ngày nay anh ấy ho dữ dội, tối cũng không ngủ được (điền từ chỉ mức độ sau 得).","required":["厉害"],"minLength":8,"chips":["这几天他咳嗽得厉害","晚上都睡不着觉"],"model":"这几天他咳嗽得厉害，晚上都睡不着觉。","modelPinyin":"lìhai","hint":"Động từ/Tính từ + 得 + 厉害"},{"promptVi":"Đặt câu hoàn chỉnh: Dạo này anh ấy bận việc dữ dội, đến cuối tuần cũng tăng ca (điền từ chỉ mức độ sau 得).","required":["厉害"],"minLength":8,"chips":["他最近工作忙得厉害","连周末都在加班"],"model":"他最近工作忙得厉害，连周末都在加班。","modelPinyin":"lìhai","hint":"Động từ/Tính từ + 得 + 厉害"}],"hsk4-thuong:6:1":[{"promptVi":"Đặt câu hoàn chỉnh: Sắp thi rồi, tôi hơi hồi hộp. — Có gì mà hồi hộp, bình thường bạn học chăm thế cơ mà (dùng mẫu 没有什么好×的).","required":["没有什么","的"],"minLength":8,"chips":["快要考试了","我有点儿紧张","没有什么好紧张的","你平时学得那么认真"],"model":"A：快要考试了，我有点儿紧张。\nB：没有什么好紧张的，你平时学得那么认真。","modelPinyin":"méiyǒu shénme hǎo jǐnzhāng de","hint":"（没）有什么（好）+ động/tính từ + 的"},{"promptVi":"Đặt câu hoàn chỉnh: Lần này thi không tốt, tôi ngại quá. — Có gì mà ngại, lần sau cố gắng là được (dùng mẫu 有什么×的).","required":[["有什么","没有什么"]],"minLength":8,"chips":["这次没考好","我很不好意思","有什么不好意思的","下次努力就行了"],"model":"A：这次没考好，我很不好意思。\nB：有什么不好意思的，下次努力就行了。","modelPinyin":"yǒu shénme bù hǎoyìsi de","hint":"（没）有什么（好）+ động/tính từ + 的"}],"hsk4-thuong:6:2":[{"promptVi":"Đặt câu hoàn chỉnh: Bình thường sức khỏe anh ấy rất tốt, thỉnh thoảng mới cảm một lần (dùng 偶尔).","required":["偶尔"],"minLength":8,"chips":["他平时身体很好","偶尔才会感冒一次"],"model":"他平时身体很好，偶尔才会感冒一次。","modelPinyin":"ǒu'ěr cái huì gǎnmào yí cì","hint":"偶尔 + (才/会) + động từ"},{"promptVi":"Đặt câu hoàn chỉnh: Tôi thường nấu ăn ở nhà, thỉnh thoảng mới ra ngoài ăn với bạn một bữa (dùng 偶尔).","required":["偶尔"],"minLength":8,"chips":["我一般在家做饭","偶尔跟朋友出去吃一顿"],"model":"我一般在家做饭，偶尔跟朋友出去吃一顿。","modelPinyin":"ǒu'ěr gēn péngyou chūqù chī yí dùn","hint":"偶尔 + (才/会) + động từ"}],"hsk4-thuong:6:3":[{"promptVi":"Đặt câu hoàn chỉnh: Sao bác sĩ còn phải chụp phim trước? — Chụp phim xem trước, để quyết định có cần tiêm hay không (vế sau dùng 好 chỉ mục đích).","required":["好"],"minLength":8,"chips":["医生为什么还要先拍片子","先拍个片子看看","好决定要不要打针"],"model":"A：医生为什么还要先拍片子？\nB：先拍个片子看看，好决定要不要打针。","modelPinyin":"hǎo juédìng yào bù yào dǎzhēn","hint":"Hành động，好 + mục đích"},{"promptVi":"Đặt câu chỉ mục đích với \"好\": \"Hãy nói rõ ràng một chút để mọi người đều nghe hiểu.\"","required":[["好"]],"minLength":5,"chips":["请说清楚一点","好让","大家","都","听得懂"],"model":"请说清楚一点，好让大家都能听懂。","modelPinyin":"Qǐng shuō qīngchu yìdiǎn, hǎo ràng dàjiā dōu néng tīngdǒng.","hint":"[Hành động], 好 (+ 让) + [mục đích]"}],"hsk4-thuong:7:0":[{"promptVi":"Đặt câu hoàn chỉnh: Về khoản máy tính, anh ấy giỏi hơn tôi, tôi phải học hỏi anh ấy nhiều (phần khuyết dùng mẫu 在……方面).","required":["方面"],"minLength":8,"chips":["在电脑方面","他做得比我好","我得多向他学习"],"model":"在电脑方面，他做得比我好，我得多向他学习。","modelPinyin":"zài diànnǎo fāngmiàn","hint":"在 + lĩnh vực + 方面，…"},{"promptVi":"Đặt câu hoàn chỉnh: Cô ấy làm việc rất nỗ lực, về mặt chi tiết chưa bao giờ qua loa (phần khuyết dùng mẫu 在……方面).","required":["方面"],"minLength":8,"chips":["她工作很努力","在细节方面从来不马虎"],"model":"她工作很努力，在细节方面从来不马虎。","modelPinyin":"zài xìjié fāngmiàn","hint":"在 + lĩnh vực + 方面，…"}],"hsk4-thuong:7:1":[{"promptVi":"Đặt câu hoàn chỉnh: Mọi người đều đồng ý kế hoạch này chứ? — Đều đồng ý. Đã vậy thì mai chúng ta bắt đầu nhé (phần khuyết bắt đầu bằng 既然).","required":["既然"],"minLength":8,"chips":["大家都同意这个计划吗","都同意","既然大家都同意","我们明天就开始吧"],"model":"A：大家都同意这个计划吗？\nB：都同意。既然大家都同意，我们明天就开始吧。","modelPinyin":"jìrán dàjiā dōu tóngyì","hint":"既然 + tiền đề đã rõ，就 + kết luận/quyết định"},{"promptVi":"Đặt câu hoàn chỉnh: Đã quyết định rồi thì đừng sửa đi sửa lại nữa (phần khuyết bắt đầu bằng 既然).","required":["既然"],"minLength":8,"chips":["既然已经决定了","就不要再改来改去了"],"model":"既然已经决定了，就不要再改来改去了。","modelPinyin":"jìrán yǐjīng juédìng le","hint":"既然 + tiền đề đã rõ，就 + kết luận/quyết định"}],"hsk4-thuong:7:2":[{"promptVi":"Đặt câu hoàn chỉnh: Thành phố này thay đổi thật lớn. Lấy giao thông mà nói, mười năm trước ở đây còn chưa có tàu điện ngầm (phần khuyết dùng mẫu 拿……来说).","required":["拿","来说"],"minLength":8,"chips":["这座城市变化真大","拿交通来说","十年前这里还没有地铁呢"],"model":"这座城市变化真大。拿交通来说，十年前这里还没有地铁呢。","modelPinyin":"ná jiāotōng lái shuō","hint":"拿 + khía cạnh/ví dụ + 来说，…"},{"promptVi":"Đặt câu với \"拿……来说\": \"Lấy tôi ra mà nói, mỗi ngày tôi đều luyện đọc 20 phút.\"","required":[["拿"],["来说"]],"minLength":5,"chips":["拿我来说","每天","我都会","练习阅读","二十分钟"],"model":"拿我来说，每天我都会练习阅读二十分钟。","modelPinyin":"Ná wǒ láishuō, měitiān wǒ dōu huì liànxí yuèdú èrshí fēnzhōng.","hint":"拿 + [ví dụ] + 来说，..."}],"hsk4-thuong:7:3":[{"promptVi":"Đặt câu hoàn chỉnh: Tham gia hoạt động giao lưu khiến tôi thích nghi với môi trường mới nhanh hơn (dùng 使).","required":["使"],"minLength":8,"chips":["参加交流活动","使我更快地适应了新环境"],"model":"参加交流活动，使我更快地适应了新环境。","modelPinyin":"shǐ wǒ gèng kuài de shìyìng le xīn huánjìng","hint":"Chủ ngữ + 使 + tân ngữ + cụm động từ"},{"promptVi":"Đặt câu hoàn chỉnh: Phương pháp mới này đơn giản dễ dùng, khiến công việc của mọi người nhẹ đi nhiều (dùng 使).","required":["使"],"minLength":8,"chips":["这个新方法简单又好用","使大家的工作轻松了不少"],"model":"这个新方法简单又好用，使大家的工作轻松了不少。","modelPinyin":"shǐ dàjiā de gōngzuò qīngsōng le bù shǎo","hint":"Chủ ngữ + 使 + tân ngữ + cụm động từ"}],"hsk4-thuong:8:0":[{"promptVi":"Đặt câu hoàn chỉnh: Ngày nào anh ấy cũng chạy bộ, dù thời tiết thế nào cũng không nghỉ (dùng 不管……都……).","required":["不管","都"],"minLength":8,"chips":["他每天都跑步","不管天气怎么样都不停"],"model":"他每天都跑步，不管天气怎么样都不停。","modelPinyin":"bùguǎn tiānqì zěnmeyàng dōu bù tíng","hint":"不管 + điều kiện thay đổi，都/也 + kết quả không đổi"},{"promptVi":"Đặt câu hoàn chỉnh: Mai mưa chúng ta còn đi ngoại ô không? — Đi, dù mưa hay không tôi cũng đi (dùng 不管……都……).","required":["不管","都"],"minLength":8,"chips":["明天下雨我们还去郊区吗","去","不管下不下雨","我都去"],"model":"A：明天下雨我们还去郊区吗？\nB：去，不管下不下雨，我都去。","modelPinyin":"bùguǎn xià bù xià yǔ, wǒ dōu qù","hint":"不管 + điều kiện thay đổi，都/也 + kết quả không đổi"}],"hsk4-thuong:8:1":[{"promptVi":"Đặt câu hoàn chỉnh: Tối nay nghỉ sớm đi, nếu không mai không dậy nổi (vế sau dùng 否则).","required":["否则"],"minLength":8,"chips":["今晚早点儿休息","否则明天早上起不来"],"model":"今晚早点儿休息，否则明天早上起不来。","modelPinyin":"fǒuzé míngtiān zǎoshang qǐ bù lái","hint":"Việc nên làm，否则 + hậu quả xấu"},{"promptVi":"Đặt câu hoàn chỉnh: Dạo này ngày nào tôi cũng thức khuya, mệt lắm. — Đừng thức khuya nữa, nếu không sức khỏe sẽ có vấn đề (dùng 否则).","required":["否则"],"minLength":8,"chips":["我最近天天熬夜","累得很","别再熬夜了","否则身体会出问题的"],"model":"A：我最近天天熬夜，累得很。\nB：别再熬夜了，否则身体会出问题的。","modelPinyin":"fǒuzé shēntǐ huì chū wèntí de","hint":"Việc nên làm，否则 + hậu quả xấu"}],"hsk4-thuong:8:2":[{"promptVi":"Đặt câu hoàn chỉnh: So với khu trung tâm náo nhiệt, tôi thích vùng ngoại ô yên tĩnh hơn (phần khuyết dùng mẫu 跟……相比).","required":["跟","相比"],"minLength":8,"chips":["跟热闹的市区相比","我更喜欢安静的郊区"],"model":"跟热闹的市区相比，我更喜欢安静的郊区。","modelPinyin":"gēn rènao de shìqū xiāngbǐ","hint":"跟 + đối tượng so sánh + 相比，+ kết luận (thường có 更）"},{"promptVi":"Đặt câu hoàn chỉnh: So với đi máy bay, đi tàu cao tốc nhanh hơn mà cũng thoải mái hơn (phần khuyết dùng mẫu 跟……相比).","required":["跟","相比"],"minLength":8,"chips":["跟坐飞机相比","坐高铁去更快","也更舒服"],"model":"跟坐飞机相比，坐高铁去更快，也更舒服。","modelPinyin":"gēn zuò fēijī xiāngbǐ","hint":"跟 + đối tượng so sánh + 相比，+ kết luận (thường có 更）"}],"hsk4-thuong:8:3":[{"promptVi":"Đặt câu hoàn chỉnh: Sân nhà nông ở ngoại ô thật tuyệt, có hoa có cỏ, không khí còn đặc biệt trong lành (dùng mẫu 有A有B).","required":["有","有"],"minLength":8,"chips":["郊区的农家小院真不错","有花有草","空气还特别好"],"model":"郊区的农家小院真不错，有花有草，空气还特别好。","modelPinyin":"yǒu huā yǒu cǎo","hint":"有 + A + 有 + B"},{"promptVi":"Đặt câu với \"有A有B\": \"Trong cửa hàng có đủ loại (có to có nhỏ / có đắt có rẻ).\"","required":[["有"]],"minLength":5,"chips":["这家店里的东西","有贵有便宜","选择","很多","有大有小"],"model":"这家店里的水果有大有小，都很新鲜。","modelPinyin":"Zhè jiā diàn lǐ de shuǐguǒ yǒu dà yǒu xiǎo, dōu hěn xīnxiān.","hint":"有 + [tính từ A] + 有 + [tính từ B]"}],"hsk4-thuong:9:0":[{"promptVi":"Đặt câu hoàn chỉnh: Có cần tôi nói với anh ấy không? — Không cần, bạn không nói anh ấy cũng biết (dùng mẫu 不……也……).","required":["不","也"],"minLength":8,"chips":["要我告诉他吗","不用","你不说他也知道"],"model":"A：要我告诉他吗？\nB：不用，你不说他也知道。","modelPinyin":"nǐ bù shuō tā yě zhīdào","hint":"Không + việc gì，也 + kết quả vẫn xảy ra"},{"promptVi":"Đặt câu hoàn chỉnh: Bài này khó quá, không xem đáp án tôi cũng không làm ra được (dùng mẫu 不……也……).","required":["不","也"],"minLength":8,"chips":["这道题太难了","我不看答案也做不出来"],"model":"这道题太难了，我不看答案也做不出来。","modelPinyin":"wǒ bù kàn dá'àn yě zuò bù chūlai","hint":"Không + việc gì，也 + kết quả vẫn xảy ra"}],"hsk4-thuong:9:1":[{"promptVi":"Đặt câu hoàn chỉnh: Hai bạn tính cách hoàn toàn khác nhau, sao thành bạn thân được? — Mặc dù tính cách khác nhau nhưng chúng tôi có nhiều sở thích chung (dùng 尽管……，但是……).","required":["尽管",["但是","可是"]],"minLength":8,"chips":["你们俩性格完全不一样","怎么成了好朋友","尽管性格不同","但是我们有很多共同爱好"],"model":"A：你们俩性格完全不一样，怎么成了好朋友？\nB：尽管性格不同，但是我们有很多共同爱好。","modelPinyin":"jǐnguǎn xìnggé bùtóng, dànshì wǒmen yǒu hěn duō gòngtóng àihào","hint":"尽管 + tiền đề nhượng bộ，但是/可是 + ý trái ngược"},{"promptVi":"Đặt câu hoàn chỉnh: Mặc dù công việc rất bận, anh ấy vẫn kiên trì chạy bộ mỗi ngày (phần khuyết bắt đầu bằng 尽管).","required":["尽管"],"minLength":8,"chips":["尽管工作很忙","他还是每天坚持跑步"],"model":"尽管工作很忙，他还是每天坚持跑步。","modelPinyin":"jǐnguǎn gōngzuò hěn máng","hint":"尽管 + tiền đề nhượng bộ，但是/可是 + ý trái ngược"}],"hsk4-thuong:9:2":[{"promptVi":"Đặt câu hoàn chỉnh: Hoạt động lần này rất thành công, mọi người đều chơi rất vui (điền 此次 ở đầu câu).","required":["此"],"minLength":8,"chips":["此次活动非常成功","大家都玩得很开心"],"model":"此次活动非常成功，大家都玩得很开心。","modelPinyin":"cǐ cì","hint":"此 + lượng/danh từ · 从此 / 因此 / 此外"},{"promptVi":"Đặt câu hoàn chỉnh: Chuyến công tác đó khiến họ quen nhau, từ đó trở thành bạn tốt (vế sau bắt đầu bằng 从此).","required":["从此"],"minLength":8,"chips":["那次出差让他们认识了","从此成了好朋友"],"model":"那次出差让他们认识了，从此成了好朋友。","modelPinyin":"cóngcǐ chéng le hǎo péngyou","hint":"此 + lượng/danh từ · 从此 / 因此 / 此外"}],"hsk4-thuong:9:3":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy là người rất thật thà, chưa bao giờ nói dối (dùng 从来 với phủ định).","required":["从来"],"minLength":8,"chips":["他这个人很实在","从来不说假话"],"model":"他这个人很实在，从来不说假话。","modelPinyin":"cónglái bù shuō jiǎhuà","hint":"从来 + 没(有)/不 + động từ · 从来都是…"},{"promptVi":"Đặt câu với \"从来\": \"Từ trước đến nay tôi chưa từng thấy phong cảnh đẹp như vậy.\"","required":[["从来"]],"minLength":5,"chips":["我","从来","没有见过","这么美的","风景"],"model":"我从来没有见过这么美的风景。","modelPinyin":"Wǒ cónglái méiyǒu jiànguò zhème měi de fēngjǐng.","hint":"Chủ ngữ + 从来 + 没(有)/不 + động từ"}],"hsk4-thuong:10:0":[{"promptVi":"Đặt câu hoàn chỉnh: Hoạt động ngày mai bạn đến được không? — Lần này dù thế nào cũng phải đi xem (dùng mẫu 说什么也得).","required":["说什么","也得"],"minLength":8,"chips":["明天的活动你能来吗","这次说什么也得去看看"],"model":"A：明天的活动你能来吗？\nB：这次说什么也得去看看。","modelPinyin":"zhè cì shuō shénme yě děi qù kànkan","hint":"说什么/怎么着 + 也得 + việc phải làm"},{"promptVi":"Đặt câu hoàn chỉnh: Sủi cảo bà ngoại làm ngon quá, hôm nay dù thế nào cũng phải ăn thêm mấy cái (dùng mẫu 说什么也得).","required":["说什么","也得"],"minLength":8,"chips":["外婆做的饺子太好吃了","今天说什么也得多吃几个"],"model":"外婆做的饺子太好吃了，今天说什么也得多吃几个。","modelPinyin":"shuō shénme yě děi duō chī jǐ ge","hint":"说什么/怎么着 + 也得 + việc phải làm"}],"hsk4-thuong:10:1":[{"promptVi":"Đặt câu hoàn chỉnh: Thời gian có đủ không? Tôi sợ không kịp. — Đừng lo, chúng ta có đầy thời gian (dùng 有的是).","required":["有的是"],"minLength":8,"chips":["时间够吗","我怕来不及","别担心","我们有的是时间"],"model":"A：时间够吗？我怕来不及。\nB：别担心，我们有的是时间。","modelPinyin":"wǒmen yǒu de shì shíjiān","hint":"有的是 + danh từ"},{"promptVi":"Đặt câu hoàn chỉnh: Dịp Tết, trong nhà có đầy món ngon, mọi người cứ ăn tự nhiên (phần khuyết dùng 有的是).","required":["有的是"],"minLength":8,"chips":["过年的时候","家里有的是好吃的","大家随便吃"],"model":"过年的时候，家里有的是好吃的，大家随便吃。","modelPinyin":"yǒu de shì hǎochī de","hint":"有的是 + danh từ"}],"hsk4-thuong:10:2":[{"promptVi":"Đặt câu hoàn chỉnh: Người miền Bắc thích ăn đồ bột, còn người miền Nam thích ăn cơm hơn (vế sau bắt đầu bằng 而).","required":["而"],"minLength":8,"chips":["北方人喜欢吃面食","而南方人更喜欢吃米饭"],"model":"北方人喜欢吃面食，而南方人更喜欢吃米饭。","modelPinyin":"ér nánfāng rén gèng xǐhuan chī mǐfàn","hint":"Vế 1，而 + vế 2"},{"promptVi":"Đặt câu hoàn chỉnh: Câu này nghe thì đơn giản, mà ý lại rất dễ khiến người ta hiểu lầm (vế sau bắt đầu bằng 而).","required":["而"],"minLength":8,"chips":["这句话听着简单","而意思很容易让人误会"],"model":"这句话听着简单，而意思很容易让人误会。","modelPinyin":"ér yìsi hěn róngyì ràng rén wùhuì","hint":"Vế 1，而 + vế 2"}],"hsk4-thuong:10:3":[{"promptVi":"Đặt câu hoàn chỉnh: Khi hoạt động kết thúc, thầy một lần nữa cảm ơn sự giúp đỡ của mọi người (dùng 再次).","required":["再次"],"minLength":8,"chips":["活动结束的时候","老师再次感谢了大家的帮助"],"model":"活动结束的时候，老师再次感谢了大家的帮助。","modelPinyin":"zàicì gǎnxiè le dàjiā de bāngzhù","hint":"再次 + động từ"},{"promptVi":"Đặt câu với \"再次\": \"Cảm ơn sự giúp đỡ nhiệt tình của các bạn một lần nữa.\"","required":[["再次"]],"minLength":5,"chips":["再次","感谢","大家的","热情","帮助"],"model":"再次感谢大家的热情帮助！","modelPinyin":"Zàicì gǎnxiè dàjiā de rèqíng bāngzhù!","hint":"再次 + động từ"}],"hsk4-ha:11:0":[{"promptVi":"Đặt câu hoàn chỉnh: Dù ngày mai trời mưa, chúng ta vẫn đi dạo công viên (phần khuyết chứa 也）.","required":["即使","也"],"minLength":8,"chips":["即使明天下雨","我们也要去公园散步"],"model":"即使明天下雨，我们也要去公园散步。","modelPinyin":"Wǒmen yě yào qù gōngyuán sànbù","hint":"即使 + giả thiết bất lợi，也 + kết quả không đổi"},{"promptVi":"Đặt câu hoàn chỉnh: Dù công việc có bận đến đâu, tôi vẫn mỗi ngày đọc sách tiếng Trung một lúc (phần khuyết chứa 也）.","required":["就是","也"],"minLength":8,"chips":["我就是工作再忙","也要每天读一会儿中文书"],"model":"我就是工作再忙，也要每天读一会儿中文书。","modelPinyin":"Yě yào měitiān dú yīhuìer zhōng wénshū","hint":"即使 + giả thiết bất lợi，也 + kết quả không đổi"}],"hsk4-ha:11:1":[{"promptVi":"Đặt câu hoàn chỉnh: Ngày mai sáu giờ đã phải xuất phát, tức là bạn năm giờ rưỡi đã phải dậy (điền cụm cố định).","required":["就是说"],"minLength":8,"chips":["明天六点就要出发","就是说","你五点半就得起床"],"model":"明天六点就要出发，就是说，你五点半就得起床。","modelPinyin":"Jiùshìshuō","hint":"Chủ ngữ + 就是 + giả thiết，也 + kết quả không đổi"},{"promptVi":"Đặt câu hoàn chỉnh: Ông dù đã tám mươi tuổi vẫn mỗi ngày kiên trì học máy tính (phần khuyết chứa 也）.","required":["即使","也"],"minLength":8,"chips":["爷爷即使八十岁了","也每天坚持学习电脑"],"model":"爷爷即使八十岁了，也每天坚持学习电脑。","modelPinyin":"Yě měitiān jiānchí xuéxí diànnǎo","hint":"Chủ ngữ + 就是 + giả thiết，也 + kết quả không đổi"}],"hsk4-ha:11:2":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy học tiếng Trung không phải vì thi cử, mà là vì muốn sang Trung Quốc làm việc (phần khuyết bắt đầu bằng 而是）.","required":["不是","而是"],"minLength":8,"chips":["他学中文不是为了考试","而是想去中国工作"],"model":"他学中文不是为了考试，而是想去中国工作。","modelPinyin":"érshì xiǎng qù zhōngguó gōngzuò","hint":"不是 + A，而是 + B"},{"promptVi":"Đặt câu hoàn chỉnh: Họ làm vậy không phải để con đạt điểm cao, mà là muốn giúp con hình thành thói quen tốt (phần khuyết chứa 不是）.","required":["不是","而是"],"minLength":8,"chips":["他们这样做不是为了让孩子考高分","而是想帮孩子养成好习惯"],"model":"他们这样做不是为了让孩子考高分，而是想帮孩子养成好习惯。","modelPinyin":"Tāmen zhèyàng zuò búshì wèile ràng háizi kǎo gāofēn","hint":"不是 + A，而是 + B"}],"hsk4-ha:11:3":[{"promptVi":"Đặt câu hoàn chỉnh: Cuốn sách này dù có khó đến đâu, tôi vẫn phải đọc hết nó (phần khuyết chứa 也）.","required":["就是","也"],"minLength":8,"chips":["这本书就是再难","我也要把它读完"],"model":"这本书就是再难，我也要把它读完。","modelPinyin":"Wǒ yě yào bǎ tā dúwán","hint":"Mệnh đề 1，就是说 + diễn đạt lại cùng ý"},{"promptVi":"Đặt câu với \"就是说\": \"Anh ấy không nghe máy, nghĩa là (tức là) anh ấy đang bận.\"","required":[["就是说"]],"minLength":5,"chips":["他没接电话","就是说","他现在","可能","很忙"],"model":"他没接电话，就是说他现在可能很忙。","modelPinyin":"Tā méi jiē diànhuà, jiùshì shuō tā xiànzài kěnéng hěn máng.","hint":"[Tình huống], 就是说 + [giải thích]"}],"hsk4-ha:12:0":[{"promptVi":"Đặt câu hoàn chỉnh: Kiểu dáng chiếc áo này không tệ, chỉ là màu sắc không hợp với mẹ lắm (điền cụm phủ định nhẹ).","required":["不怎么"],"minLength":8,"chips":["这件衣服的样子不错","就是颜色不怎么适合妈妈"],"model":"这件衣服的样子不错，就是颜色不怎么适合妈妈。","modelPinyin":"Bùzěnme","hint":"不怎么 + tính từ / động từ tâm lý"},{"promptVi":"Đặt câu hoàn chỉnh: Dạo này anh ấy không vui lắm, hình như có tâm sự gì (điền cụm phủ định nhẹ).","required":["不怎么"],"minLength":8,"chips":["最近他不怎么高兴","好像有什么心事"],"model":"最近他不怎么高兴，好像有什么心事。","modelPinyin":"Bùzěnme","hint":"不怎么 + tính từ / động từ tâm lý"}],"hsk4-ha:12:1":[{"promptVi":"Đặt câu phủ định kép (\"不得不\" - không thể không): \"Vì ngày mai thi rồi, hôm nay tôi đành phải ôn bài.\"","required":[["不得不"]],"minLength":5,"chips":["明天要考试了","我今天","不得不","认真","复习"],"model":"明天要考试了，我今天不得不认真复习。","modelPinyin":"Míngtiān yào kǎoshì le, wǒ jīntiān bùdébù rènzhēn fùxí.","hint":"Dùng 不得不 + động từ"},{"promptVi":"Đặt câu phủ định kép (\"没有……不……\" - không ai là không): \"Không ai là không thích món ăn cô ấy nấu.\"","required":[["没有","无"],["不"]],"minLength":5,"chips":["她做的菜","大家","没有一个人","不喜欢","吃"],"model":"她做的菜，大家没有一个不喜欢的。","modelPinyin":"Tā zuò de cài, dàjiā méiyǒu yí gè bù xǐhuan de.","hint":"没有……不…… (nhấn mạnh khẳng định)"}],"hsk4-ha:12:2":[{"promptVi":"Đặt câu hoàn chỉnh: Dù công việc bận đến đâu, anh ấy đều gọi điện cho cha mẹ (phần khuyết chứa 都）.","required":["无论","都"],"minLength":8,"chips":["无论工作多忙","他都给父母打电话"],"model":"无论工作多忙，他都给父母打电话。","modelPinyin":"Tā dōu gěi fùmǔ dǎdiànhuà","hint":"无论 + câu hỏi / “多 + tính từ”，都/也 + kết quả"},{"promptVi":"Đặt câu hoàn chỉnh: Dù bạn quyết định thế nào, tôi đều ủng hộ bạn (phần khuyết bắt đầu bằng 无论）.","required":["无论"],"minLength":8,"chips":["无论你做什么决定","我都支持你"],"model":"无论你做什么决定，我都支持你。","modelPinyin":"Wúlùn nǐ zuò shénme juédìng","hint":"无论 + câu hỏi / “多 + tính từ”，都/也 + kết quả"}],"hsk4-ha:12:3":[{"promptVi":"Đặt câu hoàn chỉnh: Cô ấy vì để chăm sóc cha mẹ mà về quê làm việc (phần khuyết bắt đầu bằng 而）.","required":["为了","而"],"minLength":8,"chips":["她为了照顾父母","而回到了老家工作"],"model":"她为了照顾父母，而回到了老家工作。","modelPinyin":"ér huídào le lǎojiā gōngzuò","hint":"为了 + mục đích，而 + hành động / kết quả"},{"promptVi":"Đặt câu hoàn chỉnh: Cha mẹ vì con cái mà nỗ lực làm việc cả đời (phần khuyết bắt đầu bằng 而）.","required":["为了","而"],"minLength":8,"chips":["父母为了孩子","而努力工作了一辈子"],"model":"父母为了孩子，而努力工作了一辈子。","modelPinyin":"ér nǔlì gōngzuò le yībèizi","hint":"为了 + mục đích，而 + hành động / kết quả"}],"hsk4-ha:13:0":[{"promptVi":"Đặt câu hoàn chỉnh: Bài này khó quá, tôi dù thế nào cũng không nghĩ ra được (phần khuyết mở đầu bằng 怎么也）.","required":["怎么"],"minLength":8,"chips":["这道题太难了","我怎么也想不出来"],"model":"这道题太难了，我怎么也想不出来。","modelPinyin":"Zěnme yě xiǎng bù chūlái","hint":"怎么 + 都/也 + phủ định （不/没 + động từ)"},{"promptVi":"Đặt câu hoàn chỉnh: Nơi này đẹp quá, ngắm thế nào cũng không chán (phần khuyết chứa 怎么…也）.","required":["怎么"],"minLength":8,"chips":["这个地方太美了","怎么看也看不够"],"model":"这个地方太美了，怎么看也看不够。","modelPinyin":"Zěnme kàn yě kàn bùgòu","hint":"怎么 + 都/也 + phủ định （不/没 + động từ)"}],"hsk4-ha:13:1":[{"promptVi":"Đặt câu hoàn chỉnh: Mấy năm nay, cuộc sống của chúng ta mỗi năm một tốt hơn (dùng mẫu 一…比一…).","required":["比"],"minLength":8,"chips":["这几年","我们的生活一年比一年好"],"model":"这几年，我们的生活一年比一年好。","modelPinyin":"Yīnián bǐ yīnián hǎo","hint":"一 + lượng từ + 比 + 一 + lượng từ + tính từ"},{"promptVi":"Đặt câu hoàn chỉnh: Luyện nửa năm rồi, tiếng Trung của anh ấy mỗi ngày một lưu loát hơn (dùng mẫu 一…比一…).","required":["比"],"minLength":8,"chips":["练了半年","他的中文一天比一天流利"],"model":"练了半年，他的中文一天比一天流利。","modelPinyin":"Yītiān bǐ yītiān liúlì","hint":"一 + lượng từ + 比 + 一 + lượng từ + tính từ"}],"hsk4-ha:13:2":[{"promptVi":"Đặt câu hoàn chỉnh: Bây giờ khoảng ba giờ, chúng ta mau xuất phát thôi (điền 大约 + giờ giấc).","required":["大约"],"minLength":8,"chips":["现在大约大约三点","我们快出发吧"],"model":"现在大约大约三点，我们快出发吧。","modelPinyin":"Dàyuē sāndiǎn","hint":"大约 + số lượng · số lượng + 左右"},{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy khoảng ba mươi tuổi, trông rất trẻ (điền từ chỉ số xấp xỉ đặt sau số).","required":["左右"],"minLength":8,"chips":["他今年三十岁左右","看起来很年轻"],"model":"他今年三十岁左右，看起来很年轻。","modelPinyin":"Zuǒyòu","hint":"大约 + số lượng · số lượng + 左右"}],"hsk4-ha:13:3":[{"promptVi":"Đặt câu hoàn chỉnh: Với tư cách là giáo viên, tôi nên quan tâm học sinh hơn (phần khuyết mở đầu bằng 作为）.","required":["作为"],"minLength":8,"chips":["作为老师","我应该多关心学生"],"model":"作为老师，我应该多关心学生。","modelPinyin":"Zuòwéi lǎoshī","hint":"作为 + danh từ (vai trò/thân phận)， + mệnh đề"},{"promptVi":"Đặt câu với \"作为\": \"Với tư cách là bạn thân, tôi nhất định sẽ ủng hộ bạn.\"","required":[["作为"]],"minLength":5,"chips":["作为","你的好朋友","我一定会","支持","你的决定"],"model":"作为你的好朋友，我一定会支持你。","modelPinyin":"Zuòwéi nǐ de hǎo péngyou, wǒ yídìng huì zhīchí nǐ.","hint":"作为 + [vai trò/danh phận], ..."}],"hsk4-ha:14:0":[{"promptVi":"Đặt câu hoàn chỉnh: Bạn xem lâu thế này, rốt cuộc muốn mua đôi giày nào? (điền phó từ truy vấn).","required":["究竟"],"minLength":8,"chips":["你看了这么久","究竟想买哪双鞋"],"model":"你看了这么久，究竟想买哪双鞋？","modelPinyin":"Jiūjìng xiǎng mǎi nǎ shuāngxié","hint":"究竟 + câu hỏi (ai/cái gì/thế nào…)"},{"promptVi":"Đặt câu hoàn chỉnh: Nhiều loại trà thế này, rốt cuộc loại nào uống ngon nhất? (điền phó từ truy vấn + câu hỏi).","required":["究竟"],"minLength":8,"chips":["这么多茶叶","究竟哪种最好喝"],"model":"这么多茶叶，究竟哪种最好喝？","modelPinyin":"Jiūjìng nǎzhǒng zuì hǎohē","hint":"究竟 + câu hỏi (ai/cái gì/thế nào…)"}],"hsk4-ha:14:1":[{"promptVi":"Đặt câu hoàn chỉnh: Mua giày trước tiên xem có vừa chân không, sau đó mới xem giá (điền từ chỉ bước đầu tiên).","required":["首先"],"minLength":8,"chips":["买鞋首先看合不合脚","然后再看价钱"],"model":"买鞋首先看合不合脚，然后再看价钱。","modelPinyin":"Shǒuxiān kànhé bùhé jiǎo","hint":"首先 + bước 1，然后/其次 + bước 2"},{"promptVi":"Đặt câu hoàn chỉnh: Chúng ta xem kiểu dáng trước, sau đó so sánh giá một chút (phần khuyết chứa 然后）.","required":["然后"],"minLength":8,"chips":["我们先看样子","然后比较一下价格"],"model":"我们先看样子，然后比较一下价格。","modelPinyin":"Ránhòu bǐjiào yīxià jiàgé","hint":"首先 + bước 1，然后/其次 + bước 2"}],"hsk4-ha:14:2":[{"promptVi":"Đặt câu hoàn chỉnh: Cửa hàng này đồ tốt, thêm vào đó nhân viên thái độ thân thiện, buôn bán ngày càng khá (phần khuyết bắt đầu bằng 加上）.","required":["加上"],"minLength":8,"chips":["这家店东西好","加上店员态度友好","生意越来越好"],"model":"这家店东西好，加上店员态度友好，生意越来越好。","modelPinyin":"Jiāshàng diànyuán tàidù yǒuhǎo","hint":"Ý 1，加上 + ý 2 (bổ sung)"},{"promptVi":"Đặt câu với \"加上\": \"Thời tiết nóng, cộng thêm đường tắc, tôi suýt nữa đến muộn.\"","required":[["加上"]],"minLength":5,"chips":["天气热","加上","路上堵车","我差点儿","迟到了"],"model":"天气太热，加上路上堵车，我差点儿迟到了。","modelPinyin":"Tiānqì tài rè, jiāshàng lùshang dǔchē, wǒ chàdiǎnr chídào le.","hint":"[Nguyên nhân 1], 加上 + [nguyên nhân 2], [kết quả]"}],"hsk4-ha:14:3":[{"promptVi":"Đặt câu hoàn chỉnh: Đối với tôi mà nói, chất lượng quan trọng hơn kiểu dáng (phần khuyết bắt đầu bằng 对于）.","required":["对于"],"minLength":8,"chips":["对于我来说","质量比样子更重要"],"model":"对于我来说，质量比样子更重要。","modelPinyin":"Duìyú wǒ láishuō","hint":"对于 + đối tượng，+ nhận xét"},{"promptVi":"Đặt câu hoàn chỉnh: Đối với chuyện mua đồ, anh ấy chưa bao giờ so sánh nghiêm túc (phần khuyết bắt đầu bằng 对于）.","required":["对于"],"minLength":8,"chips":["他对于买东西这件事","从来不认真比较"],"model":"他对于买东西这件事，从来不认真比较。","modelPinyin":"Duìyú mǎi dōngxī zhèjiàn shì","hint":"对于 + đối tượng，+ nhận xét"}],"hsk4-ha:15:0":[{"promptVi":"Đặt câu hoàn chỉnh: Từ hôm nay, tôi không bao giờ đến muộn nữa (phần khuyết chứa 再也不）.","required":["再也","不"],"minLength":8,"chips":["从今天起","我再也不迟到了"],"model":"从今天起，我再也不迟到了。","modelPinyin":"Zàiyě bù chídào le","hint":"再也 + 不/没 + động từ"},{"promptVi":"Đặt câu hoàn chỉnh: Sau khi tốt nghiệp, anh ấy không bao giờ về quê nữa (phần khuyết chứa 再也没）.","required":["再也","没"],"minLength":8,"chips":["毕业以后","他再也没有回过老家"],"model":"毕业以后，他再也没有回过老家。","modelPinyin":"Zàiyě méiyǒu huíguò lǎojiā","hint":"再也 + 不/没 + động từ"}],"hsk4-ha:15:1":[{"promptVi":"Đặt câu hoàn chỉnh: Hoạt động lần này do lớp trưởng phụ trách (phần khuyết bắt đầu bằng 由）.","required":["由"],"minLength":8,"chips":["这次活动由班长来负责"],"model":"这次活动由班长来负责。","modelPinyin":"Yóu bānzhǎng lái fùzé","hint":"由 + người/tổ chức + động từ"},{"promptVi":"Đặt câu hoàn chỉnh: Bài học ngày mai do giáo sư Vương giảng, mọi người phải nghe nghiêm túc (phần khuyết bắt đầu bằng 由）.","required":["由"],"minLength":8,"chips":["明天的课由王教授来讲","大家要认真听"],"model":"明天的课由王教授来讲，大家要认真听。","modelPinyin":"Yóuwáng jiàoshòu láijiǎng","hint":"由 + người/tổ chức + động từ"}],"hsk4-ha:15:2":[{"promptVi":"Đặt câu hoàn chỉnh: Trước khi đi phỏng vấn, anh ấy cắt qua mái tóc một chút (điền động từ lặp dạng 了+động từ).","required":["把"],"minLength":8,"chips":["去面试前","他把头发理了理"],"model":"去面试前，他把头发理了理。","modelPinyin":"Lǐlelǐ","hint":"把 + tân ngữ + động từ (+一/了） + động từ"},{"promptVi":"Đặt câu chữ 把 với động từ lặp lại: \"Bạn hãy dọn dẹp lại (收拾收拾) căn phòng này một chút đi.\"","required":[["把"],["收拾收拾","整理整理","打扫打扫","看看","想想"]],"minLength":5,"chips":["你","把","这个房间","收拾收拾","吧"],"model":"你把这个房间收拾收拾吧。","modelPinyin":"Nǐ bǎ zhège fángjiān shōushi shōushi ba.","hint":"把 + [tân ngữ] + [động từ lặp lại AA/ABAB]"}],"hsk4-ha:15:3":[{"promptVi":"Đặt câu hoàn chỉnh: Cuốn sách này không thú vị bằng cuốn kia, chúng ta xem cuốn kia đi (điền từ so sánh kém hơn).","required":["不如"],"minLength":8,"chips":["这本书不如那本有意思","我们看那本吧"],"model":"这本书不如那本有意思，我们看那本吧。","modelPinyin":"Bùrú nàběn yǒuyìsi","hint":"A + 不如 + B (+ tính từ)"},{"promptVi":"Đặt câu hoàn chỉnh: Học mười từ không bằng dùng tốt một từ (phần khuyết chứa 不如）.","required":["不如"],"minLength":8,"chips":["学十个词","不如用好一个词"],"model":"学十个词，不如用好一个词。","modelPinyin":"Bùrú yòng hǎo yígè cí","hint":"A + 不如 + B (+ tính từ)"}],"hsk4-ha:16:0":[{"promptVi":"Đặt câu hoàn chỉnh: Tôi đã hủy buổi họp ngày mai rồi (điền động từ + 了 sau 把 + tân ngữ).","required":["把","了"],"minLength":8,"chips":["我已经把明天的会议取消了"],"model":"我已经把明天的会议取消了。","modelPinyin":"Qǔxiāo le","hint":"把 + tân ngữ + động từ + 了"},{"promptVi":"Đặt câu hoàn chỉnh: Xin sửa bản kế hoạch này đi, viết chi tiết hơn một chút (điền động từ + 了）.","required":["把","了"],"minLength":8,"chips":["请把这份计划改了","写得再详细一点"],"model":"请把这份计划改了，写得再详细一点。","modelPinyin":"Gǎile","hint":"把 + tân ngữ + động từ + 了"}],"hsk4-ha:16:1":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy biết nói tiếng Trung, hơn nữa còn biết nói một chút tiếng Anh (phần khuyết chứa 并且）.","required":["并且"],"minLength":8,"chips":["他会说中文","并且会说一点儿英文"],"model":"他会说中文，并且会说一点儿英文。","modelPinyin":"Bìngqiě huì shuō yìdiǎnér yīngwén","hint":"Mệnh đề 1，并且 + mệnh đề 2 (tiến thêm một bước)"},{"promptVi":"Đặt câu hoàn chỉnh: Nhà hàng này món ăn ngon, hơn nữa giá cũng không đắt (phần khuyết chứa 并且）.","required":["并且"],"minLength":8,"chips":["这家饭馆菜好吃","并且价格也不贵"],"model":"这家饭馆菜好吃，并且价格也不贵。","modelPinyin":"Bìngqiě jiàgé yě bùguì","hint":"Mệnh đề 1，并且 + mệnh đề 2 (tiến thêm một bước)"}],"hsk4-ha:16:2":[{"promptVi":"Đặt câu hoàn chỉnh: Đừng lo, biết đâu ngày mai lại tốt lên (phần khuyết bắt đầu bằng 说不定）.","required":["说不定"],"minLength":8,"chips":["别担心","说不定明天就好了"],"model":"别担心，说不定明天就好了。","modelPinyin":"Shuōbùdìng míngtiān jiù hǎo le","hint":"说不定 + mệnh đề phỏng đoán"},{"promptVi":"Đặt câu với \"说不定\": \"Trời nhiều mây thế này, biết đâu chiều nay sẽ mưa.\"","required":[["说不定"]],"minLength":5,"chips":["云这么多","说不定","下午","会","下雨呢"],"model":"云这么多，说不定下午会下雨。","modelPinyin":"Yún zhème duō, shuōbudìng xiàwǔ huì xià yǔ.","hint":"说不定 + [phỏng đoán]"}],"hsk4-ha:16:3":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy tuổi không lớn, thế mà hiểu rất nhiều đạo lý (phần khuyết chứa 却）.","required":["却"],"minLength":8,"chips":["他年纪不大","却懂得很多道理"],"model":"他年纪不大，却懂得很多道理。","modelPinyin":"Què dǒngde hěnduō dàolǐ","hint":"Chủ ngữ + 却 + động từ (chuyển ý nhẹ)"},{"promptVi":"Đặt câu hoàn chỉnh: Ngoài trời rất lạnh, anh ấy thế mà chỉ mặc một chiếc áo len (phần khuyết chứa 却）.","required":["却"],"minLength":8,"chips":["外面很冷","他却只穿了一件毛衣"],"model":"外面很冷，他却只穿了一件毛衣。","modelPinyin":"Què zhǐ chuān le yījiàn máoyī","hint":"Chủ ngữ + 却 + động từ (chuyển ý nhẹ)"}],"hsk4-ha:17:0":[{"promptVi":"Đặt câu hoàn chỉnh: Cảm ơn bạn đưa tôi, bạn cứ đi đường bạn đi, tôi tự về được (điền mẫu 你×你的吧）.","required":["你的"],"minLength":8,"chips":["谢谢你送我","你走你的吧","我自己回去就行"],"model":"谢谢你送我，你走你的吧，我自己回去就行。","modelPinyin":"Nǐ zǒu nǐ de ba","hint":"Bạn + động từ + 你的 + 吧 (ví dụ: 你走你的吧)"},{"promptVi":"Đặt câu mẫu \"你×你的吧\": \"Bạn cứ đọc sách của bạn đi, đừng để ý đến tôi.\"","required":[["你"],["你的"]],"minLength":5,"chips":["你","看","你的书吧","不用","管我"],"model":"你看你的书吧，不用管我。","modelPinyin":"Nǐ kàn nǐ de shū ba, búyòng guǎn wǒ.","hint":"你 + [động từ] + 你的 (+ danh từ) + 吧"}],"hsk4-ha:17:1":[{"promptVi":"Đặt câu hoàn chỉnh: Ăn cơm phải ăn từng miếng một, cơ thể mới khỏe (điền mẫu 一A一B với 口）.","required":["一"],"minLength":8,"chips":["吃饭要一口一口吃","身体才好"],"model":"吃饭要一口一口吃，身体才好。","modelPinyin":"Yīkǒu yīkǒu chī","hint":"一 + A + 一 + B (hai đơn vị/động tác luân phiên)"},{"promptVi":"Đặt câu hoàn chỉnh: Học tiếng Trung phải từng bước một, không được vội (điền mẫu 一A一B với 步）.","required":["一"],"minLength":8,"chips":["学中文要一步一步来","不能着急"],"model":"学中文要一步一步来，不能着急。","modelPinyin":"Yībù yībù lái","hint":"一 + A + 一 + B (hai đơn vị/động tác luân phiên)"}],"hsk4-ha:17:2":[{"promptVi":"Đặt câu hoàn chỉnh: Huấn luyện viên khen anh ấy đã đạt tiến bộ rất lớn (phần khuyết mở đầu bằng 表扬 + người).","required":["表扬"],"minLength":8,"chips":["教练表扬他取得了很大的进步"],"model":"教练表扬他取得了很大的进步。","modelPinyin":"Biǎoyáng tā qǔdé le hěndà de jìnbù","hint":"Chủ ngữ + 表扬/批评 + tân ngữ 1 + động từ + tân ngữ 2"},{"promptVi":"Đặt câu hoàn chỉnh: Thầy phê bình anh ấy giờ học luôn đến muộn (phần khuyết mở đầu bằng 批评 + người).","required":["批评"],"minLength":8,"chips":["老师批评他上课总是迟到"],"model":"老师批评他上课总是迟到。","modelPinyin":"Pīpíng tā shàngkè zǒngshì chídào","hint":"Chủ ngữ + 表扬/批评 + tân ngữ 1 + động từ + tân ngữ 2"}],"hsk4-ha:17:3":[{"promptVi":"Đặt câu hoàn chỉnh: Ngay cả trẻ con cũng biết vận động có lợi, người lớn càng nên vận động nhiều (phần khuyết chứa 更）.","required":["连","更"],"minLength":8,"chips":["连小孩子都知道运动有好处","大人更应该多运动"],"model":"连小孩子都知道运动有好处，大人更应该多运动。","modelPinyin":"Dàrén gèng yīnggāi duō yùndòng","hint":"连 + đối tượng cực đoan + 都/也 + …, đối tượng thường + 更 + …"},{"promptVi":"Đặt câu hoàn chỉnh: Ngay cả cụ già tám mươi tuổi cũng kiên trì chơi bóng, người trẻ chúng ta càng phải rèn luyện thân thể (phần khuyết chứa 更）.","required":["连","更"],"minLength":8,"chips":["连八十岁的老人都坚持打球","我们年轻人更要锻炼身体"],"model":"连八十岁的老人都坚持打球，我们年轻人更要锻炼身体。","modelPinyin":"Wǒmen niánqīngrén gèngyào duànliànshēntǐ","hint":"连 + đối tượng cực đoan + 都/也 + …, đối tượng thường + 更 + …"}],"hsk4-ha:18:0":[{"promptVi":"Đặt câu kết cấu \"số từ + tính từ + lượng từ\": \"Uống một cốc nước ấm lớn (一大杯) thật thoải mái.\"","required":[["一大","一小","一整"]],"minLength":5,"chips":["喝了","一大杯","热茶","感觉","舒服多了"],"model":"喝了一大杯热茶，感觉舒服多了。","modelPinyin":"Hē le yí dà bēi rèchá, gǎnjué shūfu duō le.","hint":"一 + 大/小/整 + lượng từ + danh từ"},{"promptVi":"Đặt câu kết cấu \"số từ + tính từ + lượng từ\": \"Trên bàn có một chồng sách rất dày (一厚本 / 一大摞).\"","required":[["一大","一小","一厚","一长"]],"minLength":5,"chips":["桌子上","放着","一大箱","旧书","和笔记"],"model":"桌子上放着一大箱旧书。","modelPinyin":"Zhuōzi shang fàngzhe yí dà xiāng jiùshū.","hint":"一 + 大/小/厚 + lượng từ + danh từ"}],"hsk4-ha:18:1":[{"promptVi":"Đặt câu hoàn chỉnh: Xe đạp của tôi bị bạn học đạp đi mất rồi (phần khuyết mở đầu bằng 让 + người).","required":["让"],"minLength":8,"chips":["我的自行车让同学骑走了"],"model":"我的自行车让同学骑走了。","modelPinyin":"Ràng tóngxué qí zǒu le","hint":"Chủ ngữ + 让/叫 + người thực hiện + động từ + thành phần khác"},{"promptVi":"Đặt câu hoàn chỉnh: Điện thoại của anh ấy bị em trai cầm đi mất, tìm nửa ngày (phần khuyết mở đầu bằng 叫 + người).","required":["叫"],"minLength":8,"chips":["他的手机叫弟弟拿走了","找了半天"],"model":"他的手机叫弟弟拿走了，找了半天。","modelPinyin":"Jiào dìdi názǒu le","hint":"Chủ ngữ + 让/叫 + người thực hiện + động từ + thành phần khác"}],"hsk4-ha:18:2":[{"promptVi":"Đặt câu hoàn chỉnh: Rốt cuộc bạn muốn nói gì? Tôi muốn biết nguyên nhân thật sự (điền phó từ truy vấn).","required":["到底"],"minLength":8,"chips":["你到底想说什么","我想知道真正的原因"],"model":"你到底想说什么？我想知道真正的原因。","modelPinyin":"Dàodǐ xiǎng shuō shénme","hint":"到底 + câu hỏi / mệnh đề truy vấn"},{"promptVi":"Đặt câu hoàn chỉnh: Việc này rốt cuộc là ai làm? Mọi người đều muốn biết (điền phó từ truy vấn + câu hỏi).","required":["到底"],"minLength":8,"chips":["这件事到底是谁做的","大家都想知道"],"model":"这件事到底是谁做的？大家都想知道。","modelPinyin":"Dàodǐ shì shuí zuò de","hint":"到底 + câu hỏi / mệnh đề truy vấn"}],"hsk4-ha:18:3":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy công việc rất bận, tuy nhiên mỗi ngày vẫn kiên trì vận động (phần khuyết bắt đầu bằng 然而）.","required":["然而"],"minLength":8,"chips":["他工作很忙","然而每天都坚持运动"],"model":"他工作很忙，然而每天都坚持运动。","modelPinyin":"Ránér měitiān dōu jiānchí yùndòng","hint":"Mệnh đề 1，然而 + mệnh đề 2 (trái ngược)"},{"promptVi":"Đặt câu chuyển ngoặt với \"然而\": \"Anh ấy rất muốn giúp bạn, tuy nhiên năng lực có hạn.\"","required":[["然而"]],"minLength":5,"chips":["他很想帮你","然而","自己的能力","也","有限"],"model":"他很想帮你，然而自己的能力有限。","modelPinyin":"Tā hěn xiǎng bāng nǐ, rán’ér zìjǐ de nénglì yǒuxiàn.","hint":"[Vế 1], 然而 + [vế chuyển ngoặt]"}],"hsk4-ha:19:0":[{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy mỗi ngày không ở thư viện thì ở sân vận động (điền 就是 + khả năng thứ hai).","required":["就是"],"minLength":8,"chips":["他每天不是在图书馆","就是在操场"],"model":"他每天不是在图书馆，就是在操场。","modelPinyin":"Jiùshì zài cāochǎng","hint":"不是 + khả năng A，就是 + khả năng B"},{"promptVi":"Đặt câu hoàn chỉnh: Cuối tuần anh ấy không đi leo núi thì đi bơi (điền 就是 + khả năng thứ hai).","required":["就是"],"minLength":8,"chips":["周末他不是去爬山","就是去游泳"],"model":"周末他不是去爬山，就是去游泳。","modelPinyin":"Jiùshì qù yóuyǒng","hint":"不是 + khả năng A，就是 + khả năng B"}],"hsk4-ha:19:1":[{"promptVi":"Đặt câu hoàn chỉnh: Những từ mới này, nhớ được từ nào hay từ ấy (điền mẫu 一×是一×).","required":["是"],"minLength":8,"chips":["这些生词","能记一个是一个"],"model":"这些生词，能记一个是一个。","modelPinyin":"Shì yígè","hint":"Động từ + 一 + lượng từ + 是 + 一 + lượng từ"},{"promptVi":"Đặt câu hoàn chỉnh: Buổi diễn xem được buổi nào hay buổi ấy, đừng bỏ lỡ (điền mẫu 一×是一×).","required":["是"],"minLength":8,"chips":["演出能看一场是一场","别错过"],"model":"演出能看一场是一场，别错过。","modelPinyin":"Shì yīcháng","hint":"Động từ + 一 + lượng từ + 是 + 一 + lượng từ"}],"hsk4-ha:19:2":[{"promptVi":"Đặt câu hoàn chỉnh: Xin đọc bài khóa này một lượt, rồi trả lời câu hỏi (điền động từ + 一遍 sau 把）.","required":["把"],"minLength":8,"chips":["请把这篇课文读了一遍","然后回答问题"],"model":"请把这篇课文读了一遍，然后回答问题。","modelPinyin":"Dú le yībiàn","hint":"把 + tân ngữ + động từ + động lượng （一遍/一次/一下）"},{"promptVi":"Đặt câu hoàn chỉnh: Anh ấy dành hai ngày xem bộ phim đó, vẫn rất thích (điền động từ + thời lượng sau 把）.","required":["把"],"minLength":8,"chips":["他把那部电影看了两天","还是很喜欢"],"model":"他把那部电影看了两天，还是很喜欢。","modelPinyin":"Kàn le liǎngtiān","hint":"把 + tân ngữ + động từ + động lượng （一遍/一次/一下）"}],"hsk4-ha:19:3":[{"promptVi":"Đặt câu hoàn chỉnh: Thầy bảo tôi nghe bài hát này hai lượt (điền động từ + bổ ngữ động lượng sau 把）.","required":["把"],"minLength":8,"chips":["老师让我把这首歌听了两遍"],"model":"老师让我把这首歌听了两遍。","modelPinyin":"Tīng le liǎngbiàn","hint":"把 + tân ngữ + động từ + thời lượng （两天/三个小时）"},{"promptVi":"Đặt câu chữ 把 với bổ ngữ thời lượng: \"Tôi đã cất cuốn sách đó vào ngăn kéo cả tuần rồi.\"","required":[["把"],["了"]],"minLength":5,"chips":["我","把那本书","借给朋友","一个星期","了"],"model":"我把那本书借给朋友一个星期了。","modelPinyin":"Wǒ bǎ nà běn shū jiè gěi péngyou yí gè xīngqī le.","hint":"把 + [tân ngữ] + động từ + [thời lượng]"}],"hsk4-ha:20:0":[{"promptVi":"Đặt câu hoàn chỉnh: Muộn thế này rồi, lẽ nào bạn vẫn chưa về nhà sao? (điền phó từ phản vấn + câu hỏi).","required":["难道"],"minLength":8,"chips":["这么晚了","难道你还不回家吗"],"model":"这么晚了，难道你还不回家吗？","modelPinyin":"Nándào nǐ hái bù huíjiā ma","hint":"难道 + mệnh đề dạng câu hỏi (phản vấn)"},{"promptVi":"Đặt câu hoàn chỉnh: Việc này ai cũng biết, lẽ nào bạn chưa nghe nói sao? (điền phó từ phản vấn + câu hỏi).","required":["难道"],"minLength":8,"chips":["这件事人人都知道","难道你没听说吗"],"model":"这件事人人都知道，难道你没听说吗？","modelPinyin":"Nándào nǐ méi tīngshuō ma","hint":"难道 + mệnh đề dạng câu hỏi (phản vấn)"}],"hsk4-ha:20:1":[{"promptVi":"Đặt câu phản vấn bằng đại từ nghi vấn (\"哪儿/怎么/谁\"): \"Việc này dễ thế, sao có thể làm sai được chứ!\"","required":[["怎么","哪儿","谁"]],"minLength":5,"chips":["这件事","这么简单","怎么会","做错","呢"],"model":"这件事这么简单，怎么会做错呢？","modelPinyin":"Zhè jiàn shì zhème jiǎndān, zěnme huì zuòcuò ne?","hint":"Dùng 怎么 / 哪儿 / 谁 + ... (+ 呢)?"},{"promptVi":"Đặt câu phản vấn với \"难道\": \"Lẽ nào bạn quên lời hứa hôm qua rồi sao?\"","required":[["难道"]],"minLength":5,"chips":["难道","你","忘了","昨天的约定","吗"],"model":"难道你忘了昨天的约定吗？","modelPinyin":"Nándào nǐ wàng le zuótiān de yuēdìng ma?","hint":"难道 + ... (+ 吗)?"}],"hsk4-ha:20:2":[{"promptVi":"Đặt câu hoàn chỉnh: Xa thì xa một chút vậy, phong cảnh đẹp là được (điền mẫu ×就×点儿吧）.","required":["就"],"minLength":8,"chips":["远就远点儿吧","风景美就行"],"model":"远就远点儿吧，风景美就行。","modelPinyin":"Jiù yuǎn diǎnér ba","hint":"Tính từ/động từ + 就 + tính từ/động từ (+点儿） + 吧"},{"promptVi":"Đặt câu hoàn chỉnh: Mệt thì mệt một chút vậy, được xem thêm mấy nơi là tốt rồi (điền mẫu ×就×点儿吧）.","required":["就"],"minLength":8,"chips":["累就累点儿吧","能多看几个地方就好"],"model":"累就累点儿吧，能多看几个地方就好。","modelPinyin":"Jiù lèi diǎnér ba","hint":"Tính từ/động từ + 就 + tính từ/động từ (+点儿） + 吧"}],"hsk4-ha:20:3":[{"promptVi":"Đặt câu hoàn chỉnh: Chúng ta xuất phát sớm một chút, nếu không sẽ tắc xe (phần khuyết bắt đầu bằng 否则）.","required":["否则"],"minLength":8,"chips":["我们早点儿出发","否则会堵车"],"model":"我们早点儿出发，否则会堵车。","modelPinyin":"Fǒuzé huì dǔchē","hint":"要是 + giả thiết，（就）+ kết quả，否则 + hậu quả ngược lại"},{"promptVi":"Đặt câu hoàn chỉnh: Nếu ngày mai mưa, chúng ta sẽ mang ô ra ngoài (phần khuyết bắt đầu bằng 要是）.","required":["要是"],"minLength":8,"chips":["要是明天下雨","我们就带伞出去"],"model":"要是明天下雨，我们就带伞出去。","modelPinyin":"Yàoshì míngtiān","hint":"要是 + giả thiết，（就）+ kết quả，否则 + hậu quả ngược lại"}]};
